from typing import Optional, Dict, Any
import socket
import ipaddress
from urllib.parse import urlparse
import json

def ipinfo_geolocate(host: str,
                     token: Optional[str] = None,
                     timeout: float = 5.0,
                     prefer_ipv4: bool = True,
                     raise_on_error: bool = False) -> Dict[str, Any]:
    """
    Resolve the given host to an IP address and fetch geolocation info from ipinfo.io.

    Parameters:
    - host: hostname, IP address, or URL (e.g. "example.com", "8.8.8.8", "http://example.com:8080", "[::1]:8000")
    - token: optional ipinfo.io token (if you have one, to increase rate limits)
    - timeout: total timeout in seconds for network operations (used for the geolocation HTTP request)
    - prefer_ipv4: if True, prefer IPv4 addresses when multiple are returned
    - raise_on_error: if True, raise exceptions on errors; otherwise return a dict containing 'success': False and error details

    Returns:
    A dictionary with at least the keys:
    - success: bool
    - ip: resolved IP address (if resolution succeeded, otherwise absent)
    - geo: parsed JSON from ipinfo.io on success
    - error: error message on failure

    Example:
    >>> ipinfo_geolocate("example.com")
    {'success': True, 'ip': '93.184.216.34', 'geo': {...}}
    """
    # Local helper to return or raise errors consistently
    def _err(msg: str, details: Any = None):
        payload = {"success": False, "error": msg}
        if details is not None:
            payload["details"] = details
        if raise_on_error:
            raise RuntimeError(json.dumps(payload))
        return payload

    # Import requests (best common HTTP client). If not available, provide helpful message.
    try:
        import requests
    except Exception as e:
        return _err("The 'requests' library is required but not installed.",
                    "Install with: pip install requests")

    if not host or not isinstance(host, str):
        return _err("Invalid host: must be a non-empty string.")

    # Extract a bare hostname/IP from possible URL/host:port forms
    def _extract_hostname(h: str) -> Optional[str]:
        h = h.strip()
        # Full URL
        if h.startswith("http://") or h.startswith("https://"):
            p = urlparse(h)
            return p.hostname
        # IPv6 in brackets [::1]:port
        if h.startswith("["):
            end = h.find("]")
            if end != -1:
                return h[1:end]
            # malformed, fall through
        # If it contains many ':' it's an IPv6 without brackets -> leave as-is
        if h.count(":") >= 2:
            return h
        # If single colon, likely host:port -> remove port
        if ":" in h:
            return h.split(":", 1)[0]
        return h

    hostname = _extract_hostname(host)
    if not hostname:
        return _err("Could not parse hostname from input.", host)

    # If hostname is already an IP, use it directly
    ip_str = None
    try:
        # ipaddress accepts both IPv4 and IPv6 textual representations
        ip_obj = ipaddress.ip_address(hostname)
        ip_str = str(ip_obj)
    except ValueError:
        # Not a literal IP; resolve via DNS
        try:
            # getaddrinfo may return multiple families; prefer IPv4 if requested
            addr_infos = socket.getaddrinfo(hostname, None, family=socket.AF_UNSPEC, type=socket.SOCK_STREAM)
            if not addr_infos:
                return _err("DNS resolution returned no addresses.", hostname)
            # select address
            chosen = None
            if prefer_ipv4:
                for ai in addr_infos:
                    if ai[0] == socket.AF_INET:
                        chosen = ai
                        break
            if chosen is None:
                # pick the first available
                chosen = addr_infos[0]
            # addr is like ('93.184.216.34', 0) for IPv4 or ('2001:db8::1', 0, 0, 0) for IPv6
            addr = chosen[4]
            ip_str = addr[0]
        except socket.gaierror as e:
            return _err("DNS resolution failed.", str(e))
        except Exception as e:
            return _err("Unexpected error during DNS resolution.", str(e))

    # At this point we have an IP address string
    # Query ipinfo.io
    url = f"https://ipinfo.io/{ip_str}/json"
    params = {}
    if token:
        params["token"] = token
    headers = {
        "Accept": "application/json",
        "User-Agent": "ipinfo-geolocate/1.0"
    }

    try:
        # split timeout into connect/read for a little more resiliency
        # requests accepts a tuple (connect_timeout, read_timeout)
        resp = requests.get(url, params=params, headers=headers, timeout=(min(3.0, timeout), timeout))
    except requests.exceptions.ConnectTimeout:
        return _err("Connection to ipinfo.io timed out.")
    except requests.exceptions.ReadTimeout:
        return _err("Read from ipinfo.io timed out.")
    except requests.exceptions.SSLError as e:
        return _err("SSL error when connecting to ipinfo.io.", str(e))
    except requests.exceptions.RequestException as e:
        return _err("Network error when connecting to ipinfo.io.", str(e))

    # Check HTTP status
    if resp.status_code != 200:
        # If ipinfo returns JSON error body, try to include it
        body = None
        try:
            body = resp.json()
        except Exception:
            body = resp.text[:1000]
        return _err(f"ipinfo.io returned HTTP {resp.status_code}.", {"status": resp.status_code, "body": body})

    # Parse JSON safely
    try:
        data = resp.json()
    except ValueError:
        return _err("Failed to parse JSON response from ipinfo.io.", resp.text[:1000])

    # ipinfo may return {"error": {...}} on some errors; handle that
    if isinstance(data, dict) and data.get("error"):
        return _err("ipinfo.io returned an error object.", data.get("error"))

    return {
        "success": True,
        "ip": ip_str,
        "geo": data,
        "status_code": resp.status_code
    }

def veg_stats(people_to_vegs, seed=None, min_count=1, max_count=10, pick_random_person=True):
    """
    Given a dictionary mapping people -> vegetable(s), reverse it to vegetables -> people,
    assign a random count (between min_count and max_count inclusive) to each vegetable,
    and compute each vegetable's percentage share of the total counts.

    Returns a dictionary with:
      - 'veg_to_people': dict mapping vegetable -> list of people who listed it
      - 'counts': dict mapping vegetable -> assigned random count (int)
      - 'percentages': dict mapping vegetable -> percentage of total counts (float, 2 decimals)
      - 'veg_to_person': dict mapping vegetable -> a single person (chosen from those who listed it;
                         random if pick_random_person True, otherwise the first listed)
      - 'total_count': sum of all assigned counts

    Inputs:
      - people_to_vegs: dict where keys are people (hashable) and values are either:
          * a single vegetable (string or hashable), or
          * an iterable of vegetables (list/tuple/set) — each element should be hashable
      - seed: optional int to seed the random generator for reproducible counts/choices
      - min_count, max_count: range for random counts (inclusive)
      - pick_random_person: whether to pick a random person for veg_to_person when multiple people listed a veg

    Example:
      people = {'Alice': 'carrot', 'Bob': ['carrot', 'lettuce'], 'Carol': 'spinach'}
      stats = veg_stats(people, seed=1)
    """
    from collections import defaultdict
    import random
    from numbers import Number

    if seed is not None:
        random.seed(seed)

    veg_to_people = defaultdict(list)

    # Normalize input values to iterables of vegetables
    for person, vegs in people_to_vegs.items():
        # treat strings as single vegetable, but treat other iterables as collections
        if isinstance(vegs, str) or not hasattr(vegs, '__iter__') or isinstance(vegs, (bytes, bytearray)):
            veg_list = [vegs]
        else:
            # Convert sets/tuples/lists/generators into list
            veg_list = list(vegs)
        for veg in veg_list:
            veg_to_people[veg].append(person)

    # Assign random counts and compute totals
    counts = {}
    for veg in veg_to_people:
        counts[veg] = int(random.randint(min_count, max_count))

    total = sum(counts.values())

    if total > 0:
        percentages = {veg: round((cnt / total) * 100, 2) for veg, cnt in counts.items()}
    else:
        percentages = {veg: 0.0 for veg in counts}

    # Map each vegetable to a single person (either random or first listed)
    veg_to_person = {}
    for veg, people in veg_to_people.items():
        if not people:
            veg_to_person[veg] = None
        else:
            veg_to_person[veg] = (random.choice(people) if pick_random_person else people[0])

    return {
        'veg_to_people': dict(veg_to_people),
        'counts': counts,
        'percentages': percentages,
        'veg_to_person': veg_to_person,
        'total_count': total
    }

