def analyze_degrees(data, key=None):
    """
    Analyze degree values from input list.

    Parameters:
    - data: iterable of elements. Elements can be:
        * plain numbers (ints/floats) -> treated as degree values
        * dicts with a 'degree' key
        * objects with a .degree attribute
        * any element and a custom key function provided via `key`
    - key: optional. If provided, should be a callable that takes an element and returns its degree value.
           If key is a string, it will be used as a dict key or attribute name.

    Returns a dict:
    {
      'sorted_degrees': [float, ...],            # sorted ascending
      'sorted_stats': {'mean': float, 'median': float, 'mode': number},
      'fft_rounded': [int, ...],                 # magnitudes rounded to nearest int
      'fft_stats': {'mean': float, 'median': float, 'mode': int}
    }

    Raises:
    - ValueError if data is empty or cannot extract numeric degree values.
    - TypeError for invalid key argument.
    """
    import numpy as np
    import statistics

    # Validate input iterable
    try:
        iterator = iter(data)
    except TypeError:
        raise TypeError("data must be an iterable")

    # Helper to extract degree from element
    if key is None:
        def _getdeg(x):
            # if it's a number, return it
            if isinstance(x, (int, float, complex)) and not isinstance(x, bool):
                return float(x)
            # if dict-like and has 'degree' key
            try:
                if isinstance(x, dict) and 'degree' in x:
                    return float(x['degree'])
            except Exception:
                pass
            # attribute access
            try:
                val = getattr(x, 'degree')
                return float(val)
            except Exception:
                pass
            # fallback: try numeric conversion directly
            try:
                return float(x)
            except Exception:
                raise ValueError(f"Could not extract numeric 'degree' from element: {x!r}")
    else:
        # if key is string, produce function that tries dict key then attribute
        if isinstance(key, str):
            def _getdeg(x):
                # dict-like
                if isinstance(x, dict) and key in x:
                    return float(x[key])
                # attribute
                try:
                    val = getattr(x, key)
                    return float(val)
                except Exception:
                    # try direct conversion
                    try:
                        return float(x)
                    except Exception:
                        raise ValueError(f"Could not extract numeric '{key}' from element: {x!r}")
        elif callable(key):
            def _getdeg(x):
                return float(key(x))
        else:
            raise TypeError("key must be None, a string, or a callable")

    # Extract degree list
    degs = []
    for item in data:
        degs.append(_getdeg(item))

    if len(degs) == 0:
        raise ValueError("Input data is empty or no degree values extracted")

    # Sort degrees ascending
    sorted_degs = sorted(degs)

    # Compute stats for sorted list
    sorted_mean = statistics.mean(sorted_degs)
    sorted_median = statistics.median(sorted_degs)
    # Use multimode to handle multimodal sets deterministically: pick the smallest mode
    modes = statistics.multimode(sorted_degs)
    sorted_mode = min(modes) if modes else None

    # Compute FFT magnitudes on the sorted degree values
    arr = np.asarray(sorted_degs, dtype=float)
    fft_vals = np.fft.fft(arr)
    magnitudes = np.abs(fft_vals)

    # Round magnitudes to nearest integer
    fft_rounded = np.rint(magnitudes).astype(int).tolist()

    # Compute stats for rounded FFT magnitudes
    # If magnitudes list might be all ints, statistics functions will accept them
    fft_mean = float(np.mean(fft_rounded))
    fft_median = float(np.median(fft_rounded))
    # Use collections approach for mode determinism (smallest if tie)
    try:
        fft_modes = statistics.multimode(fft_rounded)
        fft_mode = int(min(fft_modes)) if fft_modes else None
    except Exception:
        # fallback: manual counting
        from collections import Counter
        cnt = Counter(fft_rounded)
        maxc = max(cnt.values())
        candidates = [k for k, v in cnt.items() if v == maxc]
        fft_mode = int(min(candidates))

    return {
        'sorted_degrees': sorted_degs,
        'sorted_stats': {
            'mean': sorted_mean,
            'median': sorted_median,
            'mode': sorted_mode
        },
        'fft_rounded': fft_rounded,
        'fft_stats': {
            'mean': fft_mean,
            'median': fft_median,
            'mode': fft_mode
        }
    }

# Example usage:
# data = [{'degree': 10}, {'degree': 3}, {'degree': 7}]
# print(analyze_degrees(data))
# or with raw numbers:
# print(analyze_degrees([10, 3, 7]))
