def create_histogram(objects, attribute, num_bins=NUM_BINS, title=None, xlabel=None,
                     ylabel='Frequency', figsize=(8, 6), show=True):
    """
    Create a histogram of a specified attribute from a list of objects and return the matplotlib Figure.

    Parameters
    - objects: iterable of items (can be objects with attributes, dicts, or any Python object).
    - attribute: str or callable
        If str: the attribute name to extract. Works for object attributes (getattr) or dict keys.
        If callable: called with each item to produce the value.
    - num_bins: int, number of bins to use (default NUM_BINS = 30).
    - title: optional str for the plot title.
    - xlabel: optional str for the x-axis label. If None, will use the attribute name (for str attribute).
    - ylabel: optional str for the y-axis label (default 'Frequency').
    - figsize: tuple, matplotlib figure size (default (8,6)).
    - show: bool, whether to call plt.show() before returning the Figure.

    Returns
    - matplotlib.figure.Figure: the created histogram figure.

    Notes
    - Non-numeric values (including None and NaN) are ignored.
    - Raises ValueError if no valid numeric values found.
    """
    # Imports kept here to make the function self-contained.
    import math
    import numbers
    import numpy as np
    import matplotlib.pyplot as plt

    if attribute is None:
        raise ValueError("attribute must be provided (str or callable).")

    # Helper to extract value from an object given attribute spec
    def _extract(item):
        if callable(attribute):
            try:
                return attribute(item)
            except Exception:
                return None
        if isinstance(item, dict):
            # allow nested keys with dot notation
            if isinstance(attribute, str) and '.' in attribute:
                cur = item
                for part in attribute.split('.'):
                    if isinstance(cur, dict) and part in cur:
                        cur = cur[part]
                    else:
                        return None
                return cur
            return item.get(attribute, None)
        # attribute is a string - first try getattr
        if isinstance(attribute, str):
            # support dotted attribute paths for objects (e.g., 'a.b.c')
            if '.' in attribute:
                cur = item
                for part in attribute.split('.'):
                    try:
                        cur = getattr(cur, part)
                    except Exception:
                        try:
                            cur = cur[part]  # try mapping access
                        except Exception:
                            return None
                return cur
            try:
                return getattr(item, attribute)
            except Exception:
                # try mapping access
                try:
                    return item[attribute]
                except Exception:
                    return None
        # Fallback
        return None

    # Extract values
    values = []
    for obj in objects:
        v = _extract(obj)
        # Filter out None
        if v is None:
            continue
        # If it's numpy number or list/array, attempt to convert to scalar
        if isinstance(v, (list, tuple, np.ndarray)):
            # Skip sequences for single-value histogram
            continue
        # Convert booleans to integers (optional)
        if isinstance(v, bool):
            v = int(v)
        # Numeric check
        if isinstance(v, numbers.Number):
            if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):
                continue
            values.append(float(v))
            continue
        # Try to coerce strings that are numeric
        if isinstance(v, str):
            try:
                fv = float(v)
            except Exception:
                continue
            if math.isnan(fv) or math.isinf(fv):
                continue
            values.append(fv)
            continue
        # Last resort: try to convert
        try:
            fv = float(v)
            if not (math.isnan(fv) or math.isinf(fv)):
                values.append(fv)
        except Exception:
            continue

    if len(values) == 0:
        raise ValueError("No valid numeric values found for attribute '{}'.".format(attribute))

    values = np.array(values, dtype=float)

    # Create plot
    fig, ax = plt.subplots(figsize=figsize)
    ax.hist(values, bins=num_bins, color='C0', edgecolor='black', alpha=0.75)
    # Labels
    if xlabel is None:
        xlabel = attribute if isinstance(attribute, str) else 'Value'
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    if title is None:
        title = f'Histogram of {xlabel}'
    ax.set_title(title)
    ax.grid(axis='y', linestyle='--', alpha=0.4)
    plt.tight_layout()

    if show:
        plt.show()

    return fig

