def xml_to_dict(xml_string: str, save_json: bool = False, json_file_path: str = "output.json") -> dict:
    """
    Convert an XML string into a Python dictionary and optionally save it as a JSON file.

    Uses xmltodict if available (recommended). If xmltodict is not installed, a built-in fallback
    based on xml.etree.ElementTree is used.

    Parameters:
    - xml_string: XML content as a string.
    - save_json: If True, saves the parsed result to the path given by json_file_path.
    - json_file_path: Path to write the JSON output when save_json is True.

    Returns:
    - A Python dict representing the XML structure.

    Examples:
    >>> result = xml_to_dict('<school><class><student>Emma</student></class></school>')
    >>> result['school']['class']['student']
    'Emma'

    >>> xml_to_dict('<data><item>1</item><item>2</item></data>', save_json=True, json_file_path='data.json')
    # Creates 'data.json' with the parsed content.
    """
    import json

    if not isinstance(xml_string, str) or not xml_string.strip():
        raise ValueError("xml_string must be a non-empty string containing XML data.")

    # Try using xmltodict for best behavior; fall back to ElementTree-based parser if not installed.
    try:
        import xmltodict  # type: ignore

        try:
            parsed = xmltodict.parse(xml_string)
        except Exception as e:
            raise ValueError(f"Failed to parse XML with xmltodict: {e}") from e

        # Convert OrderedDict to plain dict recursively by round-tripping through JSON.
        try:
            parsed_dict = json.loads(json.dumps(parsed))
        except Exception:
            # As a safe fallback, convert via a simple recursive conversion
            def _od_to_dict(obj):
                if isinstance(obj, dict):
                    return {k: _od_to_dict(v) for k, v in obj.items()}
                if isinstance(obj, list):
                    return [_od_to_dict(x) for x in obj]
                return obj
            parsed_dict = _od_to_dict(parsed)

    except ModuleNotFoundError:
        # Fallback implementation using xml.etree.ElementTree
        import xml.etree.ElementTree as ET

        try:
            root = ET.fromstring(xml_string)
        except Exception as e:
            raise ValueError(f"Failed to parse XML with ElementTree: {e}") from e

        def _elem_to_value(elem):
            """
            Convert an ElementTree Element into a Python value:
            - If element has no children and no attributes: return text (string) or '' if none.
            - If element has attributes or children: return dict with:
                - attribute keys prefixed by '@'
                - child tag names as keys (repeated tags become lists)
                - if element has meaningful text in addition to children/attributes, stored under '#text'
            """
            result = {}
            # attributes
            for k, v in elem.attrib.items():
                result['@' + k] = v

            # children
            children = list(elem)
            if children:
                for child in children:
                    tag = child.tag
                    val = _elem_to_value(child)
                    # If val is a dict with a single key equal to tag (unlikely with this helper),
                    # we should use val directly. But _elem_to_value returns the value for the element,
                    # so use it as-is.
                    if tag in result:
                        if not isinstance(result[tag], list):
                            result[tag] = [result[tag]]
                        result[tag].append(val)
                    else:
                        result[tag] = val

            text = (elem.text or "").strip()
            if text:
                if children or elem.attrib:
                    result['#text'] = text
                else:
                    # no children/attributes: return text directly
                    return text

            return result

        parsed_dict = {root.tag: _elem_to_value(root)}

    # Optionally save to JSON
    if save_json:
        try:
            with open(json_file_path, "w", encoding="utf-8") as f:
                json.dump(parsed_dict, f, ensure_ascii=False, indent=2)
        except Exception as e:
            raise IOError(f"Failed to write JSON to {json_file_path}: {e}") from e

    return parsed_dict

# If xmltodict is not installed and you prefer to install it for more predictable behavior,
# run: pip install xmltodict

Here's a self-contained Python function that converts an XML string into a dictionary and optionally saves the result as a JSON file. It uses xmltodict if available (recommended for robust XML handling) and falls back to a pure-stdlib implementation using xml.etree.ElementTree if xmltodict is not installed.

```python
import json

def task_func(xml_string: str, save_json: bool = False, json_file_path: str | None = None) -> dict:
    """
    Parse an XML string into a Python dictionary and optionally save it as JSON.

    - Uses xmltodict if available for best behavior (handles repeated tags as lists, attributes, etc.).
    - Falls back to a builtin ElementTree-based converter if xmltodict is not installed.

    Args:
        xml_string: XML content as a string.
        save_json: If True, write the parsed dictionary to a JSON file.
        json_file_path: Path for the JSON output file. If None and save_json is True, defaults to 'output.json'.

    Returns:
        A dictionary representation of the XML (top-level element included as a key).

    Examples:
        >>> result = task_func('<school><class><student>Emma</student></class></school>')
        >>> result['school']['class']['student']
        'Emma'

        >>> task_func('<data><item>1</item><item>2</item></data>', save_json=True, json_file_path='data.json')
        # Creates 'data.json' with the parsed contents.
    """
    # Try to use the convenient xmltodict library if available
    try:
        import xmltodict  # type: ignore
    except Exception:
        xmltodict = None

    if xmltodict:
        # xmltodict.parse returns OrderedDict; convert to plain dict via JSON round-trip
        parsed = xmltodict.parse(xml_string)
        parsed = json.loads(json.dumps(parsed))
    else:
        # Fallback implementation using ElementTree
        import xml.etree.ElementTree as ET

        def _elem_to_dict(elem):
            """Convert an Element (and subtree) into a dictionary `{tag: value}`."""
            node_dict = {}

            # include attributes with '@' prefix if present
            if elem.attrib:
                for k, v in elem.attrib.items():
                    node_dict[f"@{k}"] = v

            children = list(elem)
            if children:
                # group children by tag name
                child_groups = {}
                for child in children:
                    child_conv = _elem_to_dict(child)
                    # child_conv is a dict {tag: value}
                    for tag, val in child_conv.items():
                        child_groups.setdefault(tag, []).append(val)
                # assign single or list values
                for tag, vals in child_groups.items():
                    node_dict[tag] = vals if len(vals) > 1 else vals[0]
                # include text if non-empty (alongside children)
                text = (elem.text or "").strip()
                if text:
                    node_dict["#text"] = text
                return {elem.tag: node_dict}
            else:
                # no children -> return text or attributes+text
                text = (elem.text or "").strip()
                if elem.attrib:
                    # keep attributes and possibly text under '#text'
                    if text:
                        node_dict["#text"] = text
                    return {elem.tag: node_dict}
                else:
                    # simple leaf: return text (empty string if no text)
                    return {elem.tag: text}

        root = ET.fromstring(xml_string)
        parsed = _elem_to_dict(root)

    if save_json:
        if not json_file_path:
            json_file_path = "output.json"
        with open(json_file_path, "w", encoding="utf-8") as f:
            json.dump(parsed, f, ensure_ascii=False, indent=2)

    return parsed
```

Notes:
- If xmltodict is installed (recommended), this will match common xml->dict semantics (repeated tags become lists, attributes are prefixed with '@', etc.).
- The fallback implementation tries to produce similar behavior for repeated tags and attributes, though attribute/text key names are slightly opinionated (`@attr`, `#text`).
- Invalid XML will raise the underlying parsing exception (e.g., from ElementTree or xmltodict).

def count_predefined_items(list1, list2, predefined, *, include_zero=True):
    """
    Combine two lists and return the frequency of each predefined item in the combined data.

    Uses collections.Counter (fast, memory-efficient for hashable items). If elements are
    unhashable (e.g. lists), automatically falls back to a safe equality-based count.

    Parameters:
    - list1, list2: iterables (typically lists) whose elements will be combined.
    - predefined: iterable of items to count in the combined sequence.
    - include_zero: if False, keys with zero counts are omitted from the returned dict.

    Returns:
    - dict mapping each item in `predefined` to its integer count in list1 + list2.
      Order follows the iteration order of `predefined` (Python 3.7+ preserves insertion order).

    Example:
    >>> count_predefined_items([1,2,2], [2,3], predefined=[1,2,4])
    {1: 1, 2: 3, 4: 0}
    """
    # Keep imports local so function is self-contained
    try:
        from collections import Counter
        # Counter addition avoids creating a large intermediate combined list
        counts = Counter(list1) + Counter(list2)
        result = {item: int(counts.get(item, 0)) for item in predefined}
    except TypeError:
        # Fallback for unhashable items: use equality checks (slower)
        result = {}
        for p in predefined:
            c = 0
            for x in list1:
                if x == p:
                    c += 1
            for x in list2:
                if x == p:
                    c += 1
            result[p] = c

    if not include_zero:
        # Remove zero-count entries if requested
        result = {k: v for k, v in result.items() if v != 0}

    return result

