def generate_and_compare(s: str, letters: str, min_length: int, max_length: int):
    """
    Generate a random string (length between min_length and max_length inclusive)
    using characters from `letters`, and compute its similarity to string `s`.
    Similarity is in [0.0, 1.0]; score >= 0.5 is considered 'similar'.

    Uses RapidFuzz's normalized similarity if available (preferred), otherwise
    falls back to Python's difflib.SequenceMatcher.

    Returns a dict: {'random': generated_string, 'score': float, 'similar': bool}
    """
    # Lazy imports so function remains self-contained and fallbacks are automatic
    import secrets

    try:
        # RapidFuzz preferred for speed/accuracy; normalized_similarity returns 0..1
        from rapidfuzz.distance import Levenshtein

        def _similarity(a, b):
            return float(Levenshtein.normalized_similarity(a, b))
    except Exception:
        from difflib import SequenceMatcher

        def _similarity(a, b):
            return float(SequenceMatcher(None, a, b).ratio())

    # Validate inputs
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if not isinstance(letters, (str, list, tuple)):
        raise TypeError("letters must be a string or a sequence of characters")
    if len(letters) == 0:
        raise ValueError("letters must contain at least one character")
    if not isinstance(min_length, int) or not isinstance(max_length, int):
        raise TypeError("min_length and max_length must be integers")
    if min_length < 0 or max_length < 0:
        raise ValueError("min_length and max_length must be non-negative")
    if min_length > max_length:
        raise ValueError("min_length must be <= max_length")

    # Choose length uniformly in the inclusive range
    range_width = max_length - min_length + 1
    length = min_length + (secrets.randbelow(range_width) if range_width > 1 else 0)

    # Build random string
    # If letters is a sequence other than string, ensure we can index/iterate it
    rand_str = ''.join(secrets.choice(letters) for _ in range(length))

    # Compute similarity (0.0 .. 1.0)
    score = _similarity(s, rand_str)
    similar = score >= 0.5

    return {"random": rand_str, "score": score, "similar": similar}

