def plot_monthly_bars(data,
                      year: int | None = None,
                      ax=None,
                      figsize=(10, 5),
                      color='C0',
                      rotate_xticks=45,
                      title: str | None = None,
                      show_values: bool = False,
                      value_fmt: str = '{:.2f}',
                      xlabel='Month',
                      ylabel='Value'):
    """
    Plot a bar chart of monthly data values for a single year.

    Features:
    - Accepts a variety of input formats for `data`:
      * list/tuple/np.ndarray of length 12 (values for Jan..Dec)
      * dict mapping month numbers (1-12) or month names ('Jan','January', case-insensitive) to values
      * pandas.Series indexed by month numbers or month names
      * pandas.DataFrame with two columns: ('month','value') OR any two-column DF where first col are months, second col are values
    - X-axis shows months (Jan..Dec) in calendar order.
    - Optional year in title; optional value labels on bars.

    Returns:
      matplotlib.axes.Axes object containing the plot.

    Example usage:
      plot_monthly_bars([10, 12, 8, 9, 15, 20, 22, 18, 14, 11, 9, 7], year=2024, show_values=True)
    """
    # imports inside function to keep it self-contained
    import matplotlib.pyplot as plt
    import calendar
    from collections.abc import Mapping, Sequence

    try:
        import pandas as pd
    except Exception:
        pd = None

    # helper: map month name -> month number
    month_name_to_num = {name.lower(): i for i, name in enumerate(calendar.month_name) if name}
    month_abbr_to_num = {name.lower(): i for i, name in enumerate(calendar.month_abbr) if name}

    def parse_to_series(d):
        # Return a dict mapping month_number -> value (month_number in 1..12)
        if pd is not None and isinstance(d, pd.Series):
            s = d.copy()
            idx = list(s.index)
            mapping = {}
            for k, v in zip(idx, s.values):
                if isinstance(k, (int, float)) and int(k) in range(1, 13):
                    mapping[int(k)] = v
                else:
                    key = str(k).strip().lower()
                    if key in month_name_to_num:
                        mapping[month_name_to_num[key]] = v
                    elif key in month_abbr_to_num:
                        mapping[month_abbr_to_num[key]] = v
                    else:
                        raise ValueError(f"Unrecognized month index: {k}")
            return mapping

        if pd is not None and isinstance(d, pd.DataFrame):
            # Expect first column = months, second column = values
            if d.shape[1] < 2:
                raise ValueError("DataFrame must have at least two columns: month and value")
            months = d.iloc[:, 0].tolist()
            vals = d.iloc[:, 1].tolist()
            return parse_to_series(dict(zip(months, vals)))

        if isinstance(d, Mapping):
            mapping = {}
            for k, v in d.items():
                if isinstance(k, (int, float)) and int(k) in range(1, 13):
                    mapping[int(k)] = v
                else:
                    key = str(k).strip().lower()
                    if key in month_name_to_num:
                        mapping[month_name_to_num[key]] = v
                    elif key in month_abbr_to_num:
                        mapping[month_abbr_to_num[key]] = v
                    else:
                        raise ValueError(f"Unrecognized month key: {k}")
            return mapping

        if isinstance(d, Sequence) and not isinstance(d, (str, bytes, bytearray)):
            # list-like: if length 12 assume Jan..Dec in order
            if len(d) == 12:
                return {i + 1: v for i, v in enumerate(d)}
            else:
                # If it's a sequence of pairs (month, value)
                try:
                    # try to interpret as sequence of (month, value)
                    mapping = {}
                    for item in d:
                        if isinstance(item, Sequence) and len(item) == 2:
                            k, v = item
                            if isinstance(k, (int, float)) and int(k) in range(1, 13):
                                mapping[int(k)] = v
                            else:
                                key = str(k).strip().lower()
                                if key in month_name_to_num:
                                    mapping[month_name_to_num[key]] = v
                                elif key in month_abbr_to_num:
                                    mapping[month_abbr_to_num[key]] = v
                                else:
                                    raise ValueError(f"Unrecognized month key in sequence: {k}")
                        else:
                            raise ValueError("Sequence input must be length 12 or sequence of (month, value) pairs")
                    return mapping
                except Exception as e:
                    raise ValueError("Unrecognized sequence input. Provide length-12 list or sequence of (month,value) pairs") from e

        raise ValueError("Unsupported data type for `data`. Use list/tuple/np.array of length 12, dict, pandas Series/DataFrame, or sequence of (month,value) pairs.")

    month_map = parse_to_series(data)

    # Decide which months to plot: if all 12 present, plot Jan..Dec; otherwise plot sorted keys
    months_present = sorted(month_map.keys())
    # If user provided subset but we want full 12, we could fill missing with NaN; here we'll plot only provided months but ORDERED Jan..Dec
    months_order = [m for m in range(1, 13) if m in months_present] if any(m in months_present for m in range(1,13)) else months_present

    x_labels = [calendar.month_abbr[m] for m in months_order]
    values = [month_map[m] for m in months_order]

    # create axes if not provided
    if ax is None:
        fig, ax = plt.subplots(figsize=figsize)
    else:
        fig = ax.get_figure()

    # plotting with a clean style
    try:
        import seaborn as sns
        sns.set_style("whitegrid")
    except Exception:
        ax.grid(axis='y', linestyle='--', alpha=0.4)

    x_pos = range(len(months_order))
    bars = ax.bar(x_pos, values, color=color)

    ax.set_xticks(x_pos)
    ax.set_xticklabels(x_labels, rotation=rotate_xticks)
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)

    # Title handling
    if title is None:
        if year is not None:
            ax.set_title(f"Monthly values — {year}")
        else:
            ax.set_title("Monthly values")
    else:
        ax.set_title(title if year is None else f"{title} — {year}")

    # Optionally annotate values on bars
    if show_values:
        for rect, val in zip(bars, values):
            height = rect.get_height()
            ax.annotate(value_fmt.format(val),
                        xy=(rect.get_x() + rect.get_width() / 2, height),
                        xytext=(0, 3),  # 3 points vertical offset
                        textcoords="offset points",
                        ha='center', va='bottom', fontsize='small')

    fig.tight_layout()
    return ax

