def export_function_specs(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.
    CSV columns:
      - 'Function Name': The name of the function.
      - 'Number of Arguments': The number of arguments the function takes.
      - 'Defaults': Default values for the function's arguments, if any (JSON string).
      - 'Annotations': Type annotations of the function's arguments and return value, if any (JSON string).
      - 'Is Lambda': Boolean indicating whether the function is a lambda.

    Notes:
      - `f_list` should be an iterable of callables (functions). Non-callables are ignored.
      - If a function's signature cannot be obtained (e.g., some builtins), fields will be 'N/A'.
      - Defaults and Annotations are emitted as JSON strings mapping parameter names to string representations.
    """
    import csv
    import inspect
    import json
    from collections.abc import Iterable

    def _safe_repr(obj):
        try:
            return repr(obj)
        except Exception:
            return f"<unrepresentable {type(obj).__name__}>"

    def _annotation_to_str(ann):
        # Prefer inspect.formatannotation when available (gives nicer output for typing objects)
        if ann is inspect._empty:
            return None
        fmt = getattr(inspect, "formatannotation", None)
        if callable(fmt):
            try:
                return fmt(ann)
            except Exception:
                return _safe_repr(ann)
        return _safe_repr(ann)

    if not isinstance(f_list, Iterable):
        raise TypeError("f_list must be an iterable of callables")

    fieldnames = [
        "Function Name",
        "Number of Arguments",
        "Defaults",
        "Annotations",
        "Is Lambda",
    ]

    rows = []
    for f in f_list:
        # Skip non-callables
        if not callable(f):
            continue

        # Name
        name = getattr(f, "__name__", None) or type(f).__name__ or str(f)

        # Is lambda: detect by function name "<lambda>"
        try:
            is_lambda = bool(getattr(f, "__name__", "") == "<lambda>")
        except Exception:
            is_lambda = False

        # Try to get signature
        try:
            sig = inspect.signature(f)
            params = sig.parameters  # ordered mapping
            # Count parameters: include all kinds (POSITIONAL_ONLY, POSITIONAL_OR_KEYWORD,
            # VAR_POSITIONAL, VAR_KEYWORD, KEYWORD_ONLY)
            num_args = len(params)

            # Defaults: only parameters that have defaults
            defaults_map = {}
            for pname, p in params.items():
                if p.default is not inspect._empty:
                    defaults_map[pname] = _safe_repr(p.default)

            # Annotations: parameter annotations + return annotation if present
            ann_map = {}
            for pname, p in params.items():
                ann_str = _annotation_to_str(p.annotation)
                if ann_str is not None:
                    ann_map[pname] = ann_str
            ret_ann = _annotation_to_str(sig.return_annotation)
            if ret_ann is not None:
                ann_map["return"] = ret_ann

            defaults_json = json.dumps(defaults_map, ensure_ascii=False, sort_keys=True)
            annotations_json = json.dumps(ann_map, ensure_ascii=False, sort_keys=True)

            row = {
                "Function Name": name,
                "Number of Arguments": num_args,
                "Defaults": defaults_json if defaults_map else "",
                "Annotations": annotations_json if ann_map else "",
                "Is Lambda": str(bool(is_lambda)),
            }

        except (ValueError, TypeError):
            # Could not get signature (e.g., some builtins or callables implemented in C)
            row = {
                "Function Name": name,
                "Number of Arguments": "N/A",
                "Defaults": "N/A",
                "Annotations": "N/A",
                "Is Lambda": str(bool(is_lambda)),
            }

        rows.append(row)

    # Write CSV
    with open(file_path, mode="w", newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow(r)

def export_function_specs(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.

    CSV columns:
    - 'Function Name': The name of the function.
    - 'Number of Arguments': The number of parameters in the function signature.
    - 'Defaults': JSON-ish dict of parameter -> default value (stringified) for parameters that have defaults.
    - 'Annotations': JSON-ish dict of parameter -> annotation and a 'return' key for the return annotation (stringified).
    - 'Is Lambda': True if the function is a lambda (name == '<lambda>'), else False.

    Notes:
    - Uses inspect.signature to obtain parameter and return information.
    - For builtins or callables without an inspectable signature, fields may be empty.
    - Default values and annotations are stringified using repr() to keep the CSV human-readable.
    - The CSV is written with UTF-8 encoding.

    Args:
        f_list: Iterable of callables (functions, lambdas, methods, etc.).
        file_path: Path to the output CSV file (string or Path-like).
    """
    import inspect
    import csv
    import io
    import os

    # Helper to stringify objects (defaults and annotations)
    def _stringify(obj):
        if obj is inspect._empty:
            return ""
        try:
            return repr(obj)
        except Exception:
            # Fallback to str if repr fails
            try:
                return str(obj)
            except Exception:
                return "<unrepresentable>"

    # Ensure directory exists
    parent = os.path.dirname(os.fspath(file_path))
    if parent:
        os.makedirs(parent, exist_ok=True)

    with open(file_path, mode="w", encoding="utf-8", newline="") as csvfile:
        writer = csv.DictWriter(
            csvfile,
            fieldnames=[
                "Function Name",
                "Number of Arguments",
                "Defaults",
                "Annotations",
                "Is Lambda",
            ],
        )
        writer.writeheader()

        for f in f_list:
            # Default row values
            func_name = getattr(f, "__name__", None) or type(f).__name__
            is_lambda = (getattr(f, "__name__", "") == "<lambda>")

            num_args = ""
            defaults = {}
            annotations = {}

            try:
                sig = inspect.signature(f)
                params = sig.parameters
                # Number of arguments: count all parameters (including varargs and varkw)
                num_args = len(params)

                # Defaults: parameters with .default != inspect._empty
                for pname, param in params.items():
                    if param.default is not inspect._empty:
                        defaults[pname] = _stringify(param.default)

                # Annotations: parameter annotations and return annotation
                for pname, param in params.items():
                    if param.annotation is not inspect._empty:
                        annotations[pname] = _stringify(param.annotation)
                if sig.return_annotation is not inspect._empty:
                    annotations["return"] = _stringify(sig.return_annotation)

            except (ValueError, TypeError):
                # Builtins and some callables may raise; leave fields empty or best-effort
                # Try to use __annotations__ if available
                try:
                    annos = getattr(f, "__annotations__", {})
                    if isinstance(annos, dict) and annos:
                        for k, v in annos.items():
                            annotations[k] = _stringify(v)
                except Exception:
                    pass

            # Prepare CSV-friendly string representations
            # Represent defaults and annotations as compact JSON-like strings: "{'a': '1', ...}"
            def _dict_to_str(d):
                if not d:
                    return ""
                items = []
                for k, v in d.items():
                    items.append(f"{repr(k)}: {v}")
                return "{%s}" % ", ".join(items)

            row = {
                "Function Name": func_name,
                "Number of Arguments": num_args,
                "Defaults": _dict_to_str(defaults),
                "Annotations": _dict_to_str(annotations),
                "Is Lambda": bool(is_lambda),
            }
            writer.writerow(row)

