def fetch_github_user_ascii(username, token=None, timeout=10.0):
    """
    Retrieve GitHub user data for `username` and normalize all string data to ASCII.

    - Uses `requests` if available, falls back to the standard library (`urllib`) if not.
    - Uses `unidecode` for best transliteration if available, otherwise falls back to
      `unicodedata` normalization with ASCII stripping.
    - Returns a dictionary with the same structure as the GitHub API JSON response,
      but with every string (keys and values) converted to ASCII.

    Parameters:
    - username (str): GitHub username to fetch.
    - token (str, optional): GitHub token for authenticated requests (optional).
    - timeout (float, optional): Request timeout in seconds.

    Raises:
    - ValueError: if username is empty or not a string.
    - RuntimeError: for HTTP errors or network issues.

    Example:
        data = fetch_github_user_ascii("octocat")
    """
    # --- imports with fallbacks ---
    try:
        import requests
    except Exception:
        requests = None
    try:
        from unidecode import unidecode as _unidecode
    except Exception:
        _unidecode = None
    import json
    import unicodedata
    import sys

    # --- validate input ---
    if not isinstance(username, str) or not username.strip():
        raise ValueError("username must be a non-empty string")
    username = username.strip()

    # --- prepare request ---
    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "fetch_github_user_ascii/1.0"}
    if token:
        headers["Authorization"] = f"token {token}"

    # --- perform HTTP GET (requests preferred) ---
    response_json = None
    if requests is not None:
        try:
            resp = requests.get(url, headers=headers, timeout=timeout)
        except Exception as exc:
            raise RuntimeError(f"Network error while requesting {url}: {exc}") from exc
        status = getattr(resp, "status_code", None)
        try:
            response_json = resp.json()
        except Exception:
            response_json = None
        if status != 200:
            # try to include message from JSON if present
            msg = None
            if isinstance(response_json, dict):
                msg = response_json.get("message")
            raise RuntimeError(f"GitHub API error (status={status}): {msg or resp.text}")
    else:
        # fallback to urllib
        try:
            from urllib.request import Request, urlopen
            from urllib.error import URLError, HTTPError
        except Exception as exc:
            raise RuntimeError("No HTTP client available (requests not installed and urllib import failed).") from exc
        req = Request(url, headers=headers)
        try:
            with urlopen(req, timeout=timeout) as resp:
                raw = resp.read()
                status = resp.getcode()
                try:
                    response_json = json.loads(raw.decode("utf-8"))
                except Exception:
                    response_json = None
            if status != 200:
                msg = None
                if isinstance(response_json, dict):
                    msg = response_json.get("message")
                raise RuntimeError(f"GitHub API error (status={status}): {msg or raw.decode(errors='ignore')}")
        except HTTPError as he:
            # HTTPError has code and read() method
            try:
                detail = he.read().decode("utf-8", errors="ignore")
                detail_json = json.loads(detail) if detail else None
                msg = detail_json.get("message") if isinstance(detail_json, dict) else detail
            except Exception:
                msg = str(he)
            raise RuntimeError(f"GitHub API HTTPError (status={getattr(he,'code',None)}): {msg}") from he
        except URLError as ue:
            raise RuntimeError(f"Network error while requesting {url}: {ue}") from ue

    if response_json is None:
        raise RuntimeError("Failed to decode JSON response from GitHub API.")

    # --- normalization function ---
    def _normalize_string(s):
        if not isinstance(s, str):
            return s
        # Prefer unidecode transliteration if available (best ASCII result),
        # otherwise use NFKD decomposition and strip non-ascii.
        if _unidecode is not None:
            # unidecode returns str (ASCII)
            try:
                return _unidecode(s)
            except Exception:
                pass
        # fallback
        nk = unicodedata.normalize("NFKD", s)
        return nk.encode("ascii", "ignore").decode("ascii")

    # --- recursively normalize all strings in the JSON structure ---
    def _normalize(obj):
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                # normalize keys if they are strings
                nk = _normalize_string(k) if isinstance(k, str) else k
                # normalize values recursively
                new[nk] = _normalize(v)
            return new
        elif isinstance(obj, list):
            return [_normalize(item) for item in obj]
        elif isinstance(obj, str):
            return _normalize_string(obj)
        else:
            # numbers, booleans, None remain unchanged
            return obj

    return _normalize(response_json)
