from typing import Any, Dict, Optional


def get_github_user_normalized(username: str, token: Optional[str] = None, timeout: float = 10.0) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string values to ASCII,
    and return a dictionary of the normalized data.

    - Uses the GitHub REST API: https://api.github.com/users/{username}
    - String normalization: Unicode NFKD normalization, then ASCII encoding with errors ignored.
      This removes accents and non-ASCII characters (e.g., emoji).
    - Non-string values (numbers, booleans, None) are preserved.
    - Works recursively for nested dicts/lists.

    Parameters:
    - username: GitHub username to look up.
    - token: Optional GitHub personal access token (string). If provided, used in Authorization header
             to increase rate limits / access private endpoints if permitted.
    - timeout: Request timeout in seconds (default 10s).

    Returns:
    - A dict containing the normalized user data returned by GitHub.

    Raises:
    - ValueError if the user is not found (HTTP 404).
    - requests.HTTPError for other non-200 responses.
    - requests.RequestException for network-related errors.
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"

    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "github-user-normalizer/1.0",
    }
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    try:
        resp.raise_for_status()
    except requests.HTTPError:
        # re-raise with response content for easier debugging
        raise requests.HTTPError(f"GitHub API request failed: {resp.status_code} - {resp.text}")

    data = resp.json()

    def _normalize_string(s: str) -> str:
        # NFKD normalization then strip non-ASCII by encoding/decoding.
        if not isinstance(s, str):
            s = str(s)
        normalized = unicodedata.normalize("NFKD", s)
        ascii_bytes = normalized.encode("ascii", "ignore")
        return ascii_bytes.decode("ascii").strip()

    def _normalize(obj: Any) -> Any:
        if isinstance(obj, str):
            return _normalize_string(obj)
        if isinstance(obj, bytes):
            try:
                decoded = obj.decode("utf-8", "ignore")
            except Exception:
                decoded = str(obj)
            return _normalize_string(decoded)
        if isinstance(obj, dict):
            return { _normalize_string(k) if isinstance(k, str) else k: _normalize(v) for k, v in obj.items() }
        if isinstance(obj, list):
            return [ _normalize(item) for item in obj ]
        # other types (int, float, bool, None) left as-is
        return obj

    return _normalize(data)


