def stem_freq(sentence: str) -> dict:
    """
    Stem every word in a sentence except the last, and count the frequency of each stem.

    Uses NLTK's SnowballStemmer (English). Returns a dict mapping stem -> count.

    Example:
        stem_freq("running runners ran running")  # stems "running", "runners", "ran" except last token -> counts stems of first three tokens
    """
    import re
    from collections import Counter
    try:
        from nltk.stem.snowball import SnowballStemmer
    except Exception as e:
        raise ImportError("nltk is required. Install with: pip install nltk") from e

    stemmer = SnowballStemmer("english")
    # Tokenize into words (keeps letters, digits and apostrophes), normalize to lower-case
    tokens = re.findall(r"[A-Za-z0-9']+", sentence.lower())
    if len(tokens) <= 1:
        return {}
    stems = (stemmer.stem(tok) for tok in tokens[:-1])
    return dict(Counter(stems))

