from typing import Any, Iterable
from numbers import Real

def median_nested(L: Any) -> float:
    """
    Compute the median of all numeric elements in a nested list/tuple structure.

    - Accepts arbitrary nesting of lists and tuples (e.g. [[1, 2], (3, [4, 5])]).
    - Raises ValueError if no numeric elements are found.
    - Raises TypeError if any leaf element is non-numeric (strings, None, etc.).
    - Booleans are excluded (they are subclasses of int but typically not desired here).

    Returns:
        float: the median value (NumPy is used when available; falls back to statistics).

    Examples:
        median_nested([1, [2, 3], [[4]], 5])  # -> 3.0
        median_nested([[1,2], [3,4]])         # -> 2.5
    """
    def _flatten(x: Any) -> Iterable:
        if isinstance(x, (list, tuple)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    flat = []
    for item in _flatten(L):
        # Exclude booleans explicitly
        if isinstance(item, bool):
            raise TypeError(f"Boolean encountered where numeric expected: {item!r}")
        if isinstance(item, Real):
            flat.append(item)
        else:
            raise TypeError(f"Non-numeric element encountered: {item!r}")

    if not flat:
        raise ValueError("No numeric elements found in the nested input.")

    try:
        import numpy as np
        # use numpy median for performance on large arrays; cast to float for consistency
        return float(np.median(np.asarray(flat, dtype=float)))
    except Exception:
        import statistics
        # statistics.median may return int for integer-only odd-length inputs;
        # convert to float for consistent return type
        return float(statistics.median(flat))
