def iqr_nested(L):
    """
    Calculate the interquartile range (IQR = Q3 - Q1) of all numeric elements in a nested list/iterable L.
    Arbitrarily nested iterables are flattened (strings/bytes are treated as scalars and will raise an error
    if present), and non-numeric elements raise ValueError.
    Returns a float.

    Example:
        iqr_nested([[1, 2, [3]], [4, 5]])  # returns 2.0 (Q1=2.0, Q3=4.0)
    """
    from collections.abc import Iterable
    import numbers
    import numpy as np

    def _flatten(x):
        if isinstance(x, Iterable) and not isinstance(x, (str, bytes)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    flat = list(_flatten(L))
    if len(flat) == 0:
        raise ValueError("Input contains no elements")

    # Ensure all elements are numeric
    for v in flat:
        if not isinstance(v, numbers.Number):
            raise ValueError(f"Non-numeric element encountered: {v!r}")

    arr = np.array(flat, dtype=float)
    q1, q3 = np.percentile(arr, [25, 75])
    return float(q3 - q1)

def iqr_nested(L):
    """
    Compute the interquartile range (IQR = Q3 - Q1) of all numeric elements
    contained in a nested list-like structure L (arbitrary nesting depth).
    Non-numeric items are ignored. NaN values are ignored.
    Returns a float. Raises ValueError if no numeric values are found.
    """
    from collections.abc import Iterable
    import numbers
    import numpy as np

    def _flatten(x):
        for el in x:
            if isinstance(el, Iterable) and not isinstance(el, (str, bytes)):
                yield from _flatten(el)
            else:
                yield el

    nums = []
    for v in _flatten(L):
        # accept anything castable to float (numbers, numpy scalars, etc.)
        try:
            fv = float(v)
        except (TypeError, ValueError):
            continue
        if np.isnan(fv):
            continue
        nums.append(fv)

    if not nums:
        raise ValueError("No numeric values found in the input nested list.")

    # use numpy quantile to get Q1 and Q3
    q1, q3 = np.quantile(nums, [0.25, 0.75])
    return float(q3 - q1)

