def _default_stopwords(language: str = "english") -> Set[str]:
    if _SKLEARN_STOPWORDS is not None and language.lower() == "english":
        return set(w.lower() for w in _SKLEARN_STOPWORDS)
    if _NLTK_STOPWORDS is not None:
        try:
            return set(w.lower() for w in _NLTK_STOPWORDS.words(language))
        except Exception:
            pass
    # Minimal fallback list (common English stopwords)
    return {
        "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "if", "in",
        "into", "is", "it", "no", "not", "of", "on", "or", "such", "that", "the",
        "their", "then", "there", "these", "they", "this", "to", "was", "will", "with",
        "you", "your", "i", "we", "he", "she", "his", "her", "them", "from"
    }


def count_word_frequencies(
    text: str,
    stopwords: Optional[Iterable[str]] = None,
    language: str = "english",
    min_word_length: int = 1,
) -> Counter:
    """
    Divide a multi-line string into individual lines, remove stopwords, and count word frequencies.

    Parameters:
    - text: multi-line input string
    - stopwords: optional iterable of stopwords to use (overrides language argument)
    - language: stopword language to load if stopwords is None (default "english")
    - min_word_length: minimum length of tokens to keep (default 1)

    Returns:
    - collections.Counter mapping word -> frequency (all lowercased)

    Behavior:
    - Splits text into lines using str.splitlines(), strips empty lines.
    - Tokenizes each line using a simple regex capturing alphabetic words and apostrophes
      (e.g. "don't" is treated as "don't").
    - Lowercases tokens, filters out stopwords and short tokens, then counts frequencies.
    """
    if stopwords is None:
        stopset = _default_stopwords(language)
    else:
        stopset = set(w.lower() for w in stopwords)

    # Split into individual lines
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]

    # Tokenization regex: sequences of letters and internal apostrophes (keeps "don't")
    token_re = re.compile(r"[A-Za-z]+(?:'[A-Za-z]+)?")

    counter = Counter()
    for line in lines:
        tokens = token_re.findall(line)
        for tok in tokens:
            tok_l = tok.lower()
            if len(tok_l) < min_word_length:
                continue
            if tok_l in stopset:
                continue
            counter[tok_l] += 1

    return counter


# Example usage:
if __name__ == "__main__":
    sample = """This is a sample multi-line text.
    It contains several words, some repeated words.
    Don't count the stopwords like 'the' or 'is'."""

    freqs = count_word_frequencies(sample)
    print(freqs)  # Counter of words (stopwords removed)
