from collections import Counter
from typing import List, Dict, Any

def count_xyz_values(d: List[Dict[str, Any]]) -> Dict[str, Counter]:
    """
    Count occurrences of values for keys 'x', 'y' and 'z' in a list of dictionaries.

    Args:
        d: List of dictionaries.

    Returns:
        A dict mapping each key ('x','y','z') to a collections.Counter of values found.
        Values that are lists, dicts, or sets are converted to hashable forms so they
        can be counted.
    """
    counters = {k: Counter() for k in ('x', 'y', 'z')}

    def _make_hashable(v):
        # Convert common unhashable types into hashable equivalents
        if isinstance(v, dict):
            # Sort items so equivalent dicts have same representation
            return tuple((k, _make_hashable(val)) for k, val in sorted(v.items()))
        if isinstance(v, (list, tuple)):
            return tuple(_make_hashable(i) for i in v)
        if isinstance(v, set):
            return frozenset(_make_hashable(i) for i in v)
        return v

    for item in d:
        if not isinstance(item, dict):
            continue
        for k in ('x', 'y', 'z'):
            if k in item:
                counters[k][_make_hashable(item[k])] += 1

    return counters

# Example:
