    data = [
        {'x': 1, 'y': 'a'},
        {'x': 1, 'y': 'b'},
        {'x': 2, 'z': [1, 2]},
        {'x': 1, 'z': [1, 2]},
        {'y': 'a', 'z': [1, 2]},
        {'x': {'a': 1}, 'y': 'a'}
