    _HAS_SEABORN = True
except Exception:
    _HAS_SEABORN = False


def extract_and_visualize_json_numbers(
    data: Any,
    path: Union[str, Sequence[Union[str, int]]],
    plot_type: str = "hist",
    bins: int = 30,
    figsize: Tuple[float, float] = (8, 5),
    title: Optional[str] = None,
    kde: bool = True,
    log_scale: bool = False,
    save_path: Optional[str] = None,
    show: bool = True,
) -> Tuple[pd.Series, plt.Axes]:
    """
    Extract numeric values from nested JSON-like structure following a path of keys
    and visualize them.

    Behavior:
    - `data` can be nested dicts/lists/tuples with numbers or numeric strings.
    - `path` can be:
        - a sequence of keys (str or int), e.g. ["a", "b", 0, "value"]
        - a dot-separated string e.g. "a.b.0.value"
      Special key "*" iterates over all keys at that level (wildcard).
    - If you encounter lists while descending, the function will iterate over elements.
    - Values that are numeric (int/float, excluding bool) or strings that convert
      to numbers are collected.

    Parameters:
    - plot_type: one of {"hist", "box", "violin", "kde", "ecdf"} (defaults to "hist")
    - bins: number of bins for histogram
    - figsize: figure size in inches
    - title: optional plot title
    - kde: show KDE overlay for hist (if seaborn or supported)
    - log_scale: set y-axis to log scale (useful for heavy-tailed distributions)
    - save_path: if provided, saves the figure to this path
    - show: whether to call plt.show(); set False to integrate in other UIs

    Returns:
    - (series, ax): pandas.Series of numeric values and the matplotlib Axes used.

    Raises:
    - ValueError if no numeric values are found.
    """

    # Normalize path
    if isinstance(path, str):
        # split on dots, but keep '*' as token; no advanced escaping implemented
        path_tokens: List[Union[str, int]] = []
        for token in path.split("."):
            if token == "":
                continue
            try:
                # allow numeric indices inside dot path (e.g., "arr.0.value")
                path_tokens.append(int(token))
            except Exception:
                path_tokens.append(token)
    else:
        # convert to list and normalize ints where possible
        path_tokens = []
        for token in path:
            if isinstance(token, str):
                try:
                    path_tokens.append(int(token))
                except Exception:
                    path_tokens.append(token)
            else:
                path_tokens.append(token)

    def _is_number(x: Any) -> bool:
        return isinstance(x, numbers.Real) and not isinstance(x, bool) and not math.isnan(float(x))

    def _try_parse_number(x: Any) -> Optional[float]:
        if _is_number(x):
            return float(x)
        if isinstance(x, str):
            x_strip = x.strip()
            try:
                return float(x_strip)
            except Exception:
                return None
        return None

    # Recursive extractor
    def _extract(obj: Any, tokens: Sequence[Union[str, int]]) -> Iterable[float]:
        if not tokens:
            # At the target level: collect numbers from obj
            if _is_number(obj):
                yield float(obj)
            elif isinstance(obj, str):
                val = _try_parse_number(obj)
                if val is not None:
                    yield val
            elif isinstance(obj, (list, tuple)):
                for item in obj:
                    yield from _extract(item, [])
            elif isinstance(obj, dict):
                for v in obj.values():
                    yield from _extract(v, [])
            # else: nothing to yield
            return

        key = tokens[0]
        rest = tokens[1:]

        # If obj is a list/tuple, iterate elements and try the same tokens on each element
        if isinstance(obj, (list, tuple)):
            for item in obj:
                yield from _extract(item, tokens)
            return

        # If obj is dict-like
        if isinstance(obj, dict):
            if key == "*":
                for v in obj.values():
                    yield from _extract(v, rest)
            else:
                # key could be an int used as string in dict; only direct membership is attempted
                if key in obj:
                    yield from _extract(obj[key], rest)
                else:
                    # allow stringified int keys: e.g. key=0 but dict keys are "0"
                    if isinstance(key, int):
                        sk = str(key)
                        if sk in obj:
                            yield from _extract(obj[sk], rest)
            return

        # if obj is something else (e.g., primitive) we can't descend further
        return

    values_gen = _extract(data, path_tokens)
    values_list = list(values_gen)

    # Try to coerce collected values to numeric and drop non-convertible
    series = pd.to_numeric(pd.Series(values_list), errors="coerce").dropna()
    if series.empty:
        raise ValueError(f"No numeric values found for path {path_tokens}")

    # Plotting
    fig, ax = plt.subplots(figsize=figsize)
    if title:
        ax.set_title(title)

    ptype = plot_type.lower()
    if ptype == "hist":
        if _HAS_SEABORN:
            sns.histplot(series, bins=bins, kde=kde, ax=ax)
        else:
            ax.hist(series, bins=bins, alpha=0.7)
            if kde and len(series) > 1:
                try:
                    from scipy.stats import gaussian_kde  # type: ignore

                    kde_func = gaussian_kde(series)
                    xs = pd.np.linspace(series.min(), series.max(), 200)  # type: ignore[attr-defined]
                    ax2 = ax.twinx()
                    ax2.plot(xs, kde_func(xs), color="C1")
                    ax2.set_ylabel("KDE")
                except Exception:
                    pass
        ax.set_xlabel("value")
        ax.set_ylabel("count")
    elif ptype == "box":
        if _HAS_SEABORN:
            sns.boxplot(x=series, ax=ax)
        else:
            ax.boxplot(series, vert=False)
        ax.set_xlabel("value")
    elif ptype == "violin":
        if not _HAS_SEABORN:
            # violinplot is best with seaborn; fall back to box
            if _HAS_SEABORN:
                sns.violinplot(x=series, ax=ax)
            else:
                ax.boxplot(series, vert=False)
        else:
            sns.violinplot(x=series, ax=ax)
        ax.set_xlabel("value")
    elif ptype == "kde":
        if _HAS_SEABORN:
            sns.kdeplot(series, ax=ax, fill=False)
        else:
            try:
                from scipy.stats import gaussian_kde  # type: ignore

                kde_func = gaussian_kde(series)
                xs = pd.np.linspace(series.min(), series.max(), 200)  # type: ignore[attr-defined]
                ax.plot(xs, kde_func(xs))
                ax.set_ylabel("density")
            except Exception:
                ax.plot(series.sort_values().values, pd.np.linspace(0, 1, len(series)))  # type: ignore[attr-defined]
        ax.set_xlabel("value")
    elif ptype == "ecdf":
        sorted_vals = series.sort_values().reset_index(drop=True)
        y = (sorted_vals.index + 1) / len(sorted_vals)
        ax.step(sorted_vals.values, y, where="post")
        ax.set_xlabel("value")
        ax.set_ylabel("ECDF")
    else:
        raise ValueError(f"Unknown plot_type: {plot_type}")

    if log_scale:
        ax.set_yscale("log")

    plt.tight_layout()

    if save_path:
        fig.savefig(save_path, bbox_inches="tight")

    if show:
        plt.show()

    return series.reset_index(drop=True), ax


# Example usage:
