import json
from typing import Any, Iterable, List, Optional, Sequence, Union, Dict
import numbers

import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns


def extract_and_visualize_from_json(
    json_obj: Union[str, Dict, List],
    path: Union[str, Sequence[Union[str, int]]],
    plot: str = "hist",
    bins: int = 30,
    figsize: tuple = (8, 5),
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    save_to: Optional[str] = None,
    show: bool = True,
    sns_style: str = "whitegrid",
) -> Dict[str, Any]:
    """
    Extract numerical values from a nested JSON-like structure following a path,
    and visualize them.

    Parameters:
    - json_obj: dict/list or JSON string.
    - path: sequence of keys/indexes or dot-separated string. Use '*' as a wildcard
            to iterate over all items at that level. Elements may be strings or ints.
            Example: "data.items.*.value" or ["data","items","*","value"].
    - plot: one of {"hist", "box", "line", "strip"} (default "hist").
    - bins: bins used for histogram.
    - figsize: figure size (width, height).
    - title/xlabel/ylabel: optional labels for the plot.
    - save_to: optional file path to save the figure (e.g., "out.png").
    - show: whether to call plt.show() (set False to use in non-interactive contexts).
    - sns_style: seaborn style name.

    Returns:
    A dict with keys:
      - "values": list of numeric values extracted (order preserved where applicable)
      - "series": pandas.Series of the values
      - "fig": matplotlib.figure.Figure object
      - "ax": matplotlib.axes.Axes object

    Behavior notes:
    - Booleans are excluded (since bool is subclass of int).
    - If the path ends and the target node is a list/dict, all numeric leaves under it are collected.
    - If no numeric values are found, ValueError is raised.

    Example:
      data = {
          "rows": [
              {"id": 1, "metrics": {"score": 9.5}},
              {"id": 2, "metrics": {"score": 7.2}},
              {"id": 3, "metrics": {"score": 8.1}}
          ]
      }
      extract_and_visualize_from_json(data, "rows.*.metrics.score", plot="box")
    """
    # Parse json string if needed
    if isinstance(json_obj, str):
        json_obj = json.loads(json_obj)

    # Normalize path to list
    if isinstance(path, str):
        # allow '.' separated keys, but preserve '*' and integer strings if provided
        raw_parts = path.split(".")
        parsed_path = []
        for p in raw_parts:
            if p == "*":
                parsed_path.append(p)
            else:
                # try to convert integer index tokens
                try:
                    parsed_path.append(int(p))
                except ValueError:
                    parsed_path.append(p)
        path_list = parsed_path
    else:
        path_list = list(path)

    def is_number(x: Any) -> bool:
        return isinstance(x, numbers.Real) and not isinstance(x, bool)

    def collect_numeric_leaves(node: Any) -> List[float]:
        """Recursively gather numeric leaves from node."""
        results: List[float] = []
        if is_number(node):
            results.append(float(node))
        elif isinstance(node, dict):
            for v in node.values():
                results.extend(collect_numeric_leaves(v))
        elif isinstance(node, list) or isinstance(node, tuple):
            for v in node:
                results.extend(collect_numeric_leaves(v))
        return results

    def traverse(node: Any, idx: int) -> List[float]:
        """Traverse json_obj following path_list starting at idx; return numeric values."""
        if idx >= len(path_list):
            # path finished: collect numeric leaves under node
            return collect_numeric_leaves(node)
        key = path_list[idx]

        results: List[float] = []
        # wildcard: iterate through items of dict/list
        if key == "*":
            if isinstance(node, dict):
                for v in node.values():
                    results.extend(traverse(v, idx + 1))
            elif isinstance(node, (list, tuple)):
                for v in node:
                    results.extend(traverse(v, idx + 1))
            # otherwise nothing to iterate
            return results

        # integer index (explicit)
        if isinstance(key, int):
            if isinstance(node, (list, tuple)):
                if -len(node) <= key < len(node):
                    results.extend(traverse(node[key], idx + 1))
            # index on non-list yields nothing
            return results

        # string key
        if isinstance(node, dict):
            if key in node:
                results.extend(traverse(node[key], idx + 1))
            return results

        # if node is a list/tuple and key is string, try mapping over elements
        if isinstance(node, (list, tuple)):
            for v in node:
                if isinstance(v, dict) and key in v:
                    results.extend(traverse(v[key], idx + 1))
            return results

        # otherwise nothing to do
        return results

    values = traverse(json_obj, 0)
    if not values:
        raise ValueError(f"No numerical values found at path {path_list!r}")

    # Build pandas Series
    series = pd.Series(values)

    # Plot using seaborn/matplotlib
    sns.set_style(sns_style)
    fig, ax = plt.subplots(figsize=figsize)

    plot_type = plot.lower()
    if plot_type == "hist":
        sns.histplot(series, bins=bins, kde=False, ax=ax)
        ax.set_ylabel(ylabel or "Count")
        ax.set_xlabel(xlabel or "Value")
    elif plot_type == "hist_kde":
        sns.histplot(series, bins=bins, kde=True, ax=ax)
        ax.set_ylabel(ylabel or "Density")
        ax.set_xlabel(xlabel or "Value")
    elif plot_type == "box":
        sns.boxplot(x=series, ax=ax)
        ax.set_xlabel(xlabel or "Value")
        if ylabel:
            ax.set_ylabel(ylabel)
    elif plot_type == "line":
        ax.plot(series.index, series.values, marker="o", linestyle="-")
        ax.set_xlabel(xlabel or "Index")
        ax.set_ylabel(ylabel or "Value")
    elif plot_type == "strip":
        sns.stripplot(x=series, jitter=True, ax=ax)
        ax.set_xlabel(xlabel or "Value")
    else:
        raise ValueError(f"Unsupported plot type: {plot}. Choose from hist, hist_kde, box, line, strip.")

    if title:
        ax.set_title(title)

    plt.tight_layout()

    if save_to:
        fig.savefig(save_to, bbox_inches="tight")

    if show:
        plt.show()

    return {"values": values, "series": series, "fig": fig, "ax": ax}


# Example usage:
if __name__ == "__main__":
    sample = {
        "data": {
            "items": [
                {"metrics": {"value": 10}},
                {"metrics": {"value": 7.5}},
                {"metrics": {"value": 12.3}},
