Here's a single, self-contained Python function that fetches an HTML page (from a URL or a local file), extracts an HTML table (by index or CSS selector), normalizes the data, and writes it into an SQLite database. It uses requests, BeautifulSoup (bs4), and pandas for robust parsing and sqlite3 for storage.

Copy the function into your codebase; install the required libraries if you don't have them:
- pip install pandas requests beautifulsoup4 lxml

Function:

```python
import re
import io
import sqlite3
from typing import Optional, Union, Sequence, Dict, Any

import requests
import pandas as pd
from bs4 import BeautifulSoup


def html_table_to_sqlite(
    source: str,
    sqlite_path: str,
    *,
    table_name: Optional[str] = None,
    table_index: int = 0,
    selector: Optional[str] = None,
    match: Optional[str] = None,
    if_exists: str = "fail",    # 'fail', 'replace', 'append' (for pandas route)
    primary_key: Optional[Union[str, Sequence[str]]] = None,
    conflict: str = "abort",    # 'abort' (normal), 'replace' (INSERT OR REPLACE), 'ignore' (INSERT OR IGNORE)
    parse_dates: bool = False,
    convert_numeric: bool = True,
    user_agent: Optional[str] = None,
    timeout: float = 10.0,
    encoding: Optional[str] = None,
    verbose: bool = False,
) -> Dict[str, Any]:
    """
    Parse an HTML table from a URL or local file and store it into an SQLite database.

    Parameters:
    - source: URL (http/https) or local file path to an HTML file.
    - sqlite_path: path to the SQLite file. Use ':memory:' for an in-memory DB.
    - table_name: optional name of the table in SQLite; if omitted, derived from caption or 'table_{index}'.
    - table_index: index of the table to pick (0-based) when multiple tables are present.
    - selector: optional CSS selector to pick the <table> element(s). If provided, selector takes precedence.
    - match: optional string/regex passed to pandas.read_html to match a table.
    - if_exists: passed to pandas DataFrame.to_sql if primary_key is None. One of 'fail', 'replace', 'append'.
    - primary_key: column name or list of column names to use as primary key. If provided, the function will create
                   the table schema explicitly and insert rows with the given conflict resolution.
    - conflict: one of 'abort', 'replace', 'ignore' controlling how inserts handle primary-key conflicts.
    - parse_dates: attempt to parse date-like columns (when True).
    - convert_numeric: attempt to convert object columns to numeric where possible.
    - user_agent: optional custom User-Agent header for HTTP fetches.
    - timeout: request timeout in seconds.
    - encoding: optional encoding to use when reading file/response text (otherwise auto-detected by requests or pandas).
    - verbose: print helpful messages if True.

    Returns:
    A dict with keys:
      - success: bool
      - table_name: str
      - rows_inserted: int
      - message: str (error or success detail)
      - dataframe: pandas.DataFrame (the table parsed)
    """

    # --- Helper functions ---
    def _log(*args):
        if verbose:
            print(*args)

    def _is_url(s: str) -> bool:
        return bool(re.match(r"^https?://", s, re.I))

    def _sanitize_colname(name: str) -> str:
        if name is None:
            name = ""
        name = str(name).strip()
        # Replace whitespace with underscore, remove problematic chars
        name = re.sub(r"\s+", "_", name)
        name = re.sub(r"[^\w_]", "", name)  # keep letters, numbers, underscore
        if not name:
            name = "col"
        if re.match(r"^\d", name):
            name = "c_" + name
        return name

    def _ensure_unique_columns(cols):
        seen = {}
        out = []
        for c in cols:
            base = c
            i = 1
            while c in seen:
                c = f"{base}_{i}"
                i += 1
            seen[c] = True
            out.append(c)
        return out

    def _sqlite_type_from_series(s: pd.Series) -> str:
        if pd.api.types.is_integer_dtype(s.dropna()):
            return "INTEGER"
        if pd.api.types.is_float_dtype(s.dropna()):
            return "REAL"
        if pd.api.types.is_bool_dtype(s.dropna()):
            return "INTEGER"
        if pd.api.types.is_datetime64_any_dtype(s):
            return "TEXT"
        # fallback
        return "TEXT"

    # --- Fetch content ---
    try:
        if _is_url(source):
            headers = {"User-Agent": user_agent} if user_agent else {}
            _log("Fetching URL:", source)
            resp = requests.get(source, headers=headers, timeout=timeout)
            resp.raise_for_status()
            if encoding:
                resp.encoding = encoding
            html = resp.text
        else:
            _log("Reading local file:", source)
            # open in binary and decode if encoding known
            with open(source, "rb") as f:
                raw = f.read()
            if encoding:
                html = raw.decode(encoding, errors="replace")
            else:
                # try utf-8 then fallback to latin1
                try:
                    html = raw.decode("utf-8")
                except Exception:
                    html = raw.decode("latin-1", errors="replace")
    except Exception as e:
        return {"success": False, "message": f"Failed to read source: {e}", "rows_inserted": 0}

    # --- Extract table(s) ---
    try:
        tables = []
        soup = BeautifulSoup(html, "lxml")

        if selector:
            sel = soup.select(selector)
            if not sel:
                return {"success": False, "message": f"No elements found with selector: {selector}", "rows_inserted": 0}
            # collect table HTML strings
            table_htmls = []
            for el in sel:
                if el.name == "table":
                    table_htmls.append(str(el))
                else:
                    # if a wrapper, find tables inside
                    inner = el.find_all("table")
                    if inner:
                        table_htmls.extend(str(t) for t in inner)
            if not table_htmls:
                return {"success": False, "message": f"No <table> found within selector: {selector}", "rows_inserted": 0}
            # parse each table_html via pandas
            for th in table_htmls:
                parsed = pd.read_html(io.StringIO(th), flavor="bs4", header=0, match=match)
                tables.extend(parsed)
        else:
            # use pandas.read_html for the whole document (it returns list of DataFrames)
            tables = pd.read_html(io.StringIO(html), flavor="bs4", header=0, match=match)
    except ValueError as e:
        # pandas raises ValueError if no tables found
        return {"success": False, "message": f"No tables found: {e}", "rows_inserted": 0}
    except Exception as e:
        return {"success": False, "message": f"Failed to parse HTML tables: {e}", "rows_inserted": 0}

    if not tables:
        return {"success": False, "message": "No tables parsed from source", "rows_inserted": 0}

    if table_index < 0 or table_index >= len(tables):
        return {"success": False, "message": f"table_index {table_index} out of range (0..{len(tables)-1})", "rows_inserted": 0}

    df = tables[table_index].copy()

    # If table_name not given, try to get caption text or create default
    if table_name is None:
        cap = None
        try:
            # parse caption for the relevant table quickly
            if selector:
                # if selector used, try to get the caption from selector match
                elems = soup.select(selector)
                if elems:
                    # pick appropriate element corresponding to table_index if possible
                    idx = min(table_index, len(elems) - 1)
                    el = elems[idx]
                    cap_el = el.find("caption") if getattr(el, "name", None) == "table" else el.find("caption")
                    if cap_el is not None:
                        cap = cap_el.get_text(strip=True)
            else:
                tables_el = soup.find_all("table")
                if tables_el and table_index < len(tables_el):
                    cap_el = tables_el[table_index].find("caption")
                    if cap_el:
                        cap = cap_el.get_text(strip=True)
        except Exception:
            cap = None

        if cap:
            tn = re.sub(r"\s+", "_", cap.strip())
            tn = re.sub(r"[^\w_]", "", tn)
            table_name = tn or f"table_{table_index}"
        else:
            table_name = f"table_{table_index}"

    # --- Normalize DataFrame columns and values ---
    # flatten MultiIndex headers if present
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = ["_".join([str(x) for x in col if (x is not None and str(x) != "")]).strip() for col in df.columns]

    # Clean and sanitize column names
    cols = [str(c) for c in df.columns.tolist()]
    cols = [_sanitize_colname(c) for c in cols]
    cols = _ensure_unique_columns(cols)
    df.columns = cols

    # Strip whitespace in string cells
    df = df.applymap(lambda v: v.strip() if isinstance(v, str) else v)

    # Convert numeric-like columns
    if convert_numeric:
        for col in df.columns:
            if df[col].dtype == object:
                # attempt numeric conversion
                coerced = pd.to_numeric(df[col].replace("", pd.NA), errors="coerce")
                # if many values parsed as numeric (non-null fraction > 0.5), adopt numeric
                non_null = coerced.count()
                if non_null > 0 and non_null >= (len(df[col].dropna()) / 2):
                    df[col] = coerced

    # Parse dates if requested
    if parse_dates:
        for col in df.columns:
            if df[col].dtype == object:
                try:
                    parsed = pd.to_datetime(df[col], errors="coerce", infer_datetime_format=True)
                    # adopt if at least some parsed
                    if parsed.notna().sum() >= max(1, len(df) // 10):
                        df[col] = parsed
                except Exception:
                    continue

    # Replace pandas NaN with None for sqlite insertion
    df_for_insertion = df.where(pd.notnull(df), None)

    # --- Write to SQLite ---
    rows_inserted = 0
    try:
        conn = sqlite3.connect(sqlite_path)
        cur = conn.cursor()

        if primary_key is None:
            # delegate to pandas.to_sql which handles schema and types automatically
            _log("Using pandas.to_sql for writing (no explicit primary_key).")
            df.to_sql(table_name, conn, if_exists=if_exists, index=False)
            # Count rows inserted or existing count
            cur.execute(f"SELECT COUNT(*) FROM \"{table_name}\"")
            rows_inserted = cur.fetchone()[0]
            conn.commit()
            conn.close()
            return {
                "success": True,
                "message": f"Table '{table_name}' written to {sqlite_path} (if_exists={if_exists}).",
                "rows_inserted": int(rows_inserted),
                "table_name": table_name,
                "dataframe": df,
            }
        else:
            # normalize primary_key to list
            if isinstance(primary_key, str):
                pkeys = [primary_key]
            else:
                pkeys = list(primary_key)

            pkeys = [str(pk) for pk in pkeys]
            # ensure pkeys are valid column names
            for pk in pkeys:
                if pk not in df.columns:
                    conn.close()
                    return {"success": False, "message": f"Primary key column '{pk}' not present in table columns", "rows_inserted": 0}

            # Check if table exists
            cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
            exists = cur.fetchone() is not None

            if exists and if_exists == "replace":
                _log("Dropping existing table (if_exists=replace).")
                cur.execute(f'DROP TABLE IF EXISTS "{table_name}"')
                exists = False

            if exists and if_exists == "fail":
                conn.close()
                return {"success": False, "message": f"Table '{table_name}' already exists and if_exists='fail'.", "rows_inserted": 0}

            if not exists:
                # create table with inferred sqlite types
                col_defs = []
                for col in df.columns:
                    col_type = _sqlite_type_from_series(df[col])
                    col_defs.append(f'"{col}" {col_type}')
                pk_clause = ", ".join([f'"{pk}"' for pk in pkeys])
                create_sql = f'CREATE TABLE "{table_name}" ({", ".join(col_defs)}, PRIMARY KEY ({pk_clause}))'
                _log("Creating table with SQL:", create_sql)
                cur.execute(create_sql)
                conn.commit()

            # Prepare insert statement with conflict handling
            if conflict == "replace":
                insert_prefix = "INSERT OR REPLACE INTO"
            elif conflict == "ignore":
                insert_prefix = "INSERT OR IGNORE INTO"
            else:
                insert_prefix = "INSERT INTO"

            col_list = ", ".join([f'"{c}"' for c in df.columns])
            placeholders = ", ".join(["?"] * len(df.columns))
            insert_sql = f"{insert_prefix} \"{table_name}\" ({col_list}) VALUES ({placeholders})"

            _log("Inserting rows using:", insert_sql)
            to_insert = []
            for _, row in df_for_insertion.iterrows():
                vals = []
                for val in row.tolist():
                    # convert datetimes to ISO string
                    if pd.isna(val):
                        vals.append(None)
                    elif isinstance(val, pd.Timestamp):
                        vals.append(val.isoformat())
                    else:
                        vals.append(val)
                to_insert.append(tuple(vals))

            cur.executemany(insert_sql, to_insert)
            rows_inserted = cur.rowcount if cur.rowcount != -1 else len(to_insert)
            conn.commit()
            conn.close()
            return {
                "success": True,
                "message": f"Inserted {rows_inserted} rows into '{table_name}' in {sqlite_path}.",
                "rows_inserted": int(rows_inserted),
                "table_name": table_name,
                "dataframe": df,
            }
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        return {"success": False, "message": f"SQLite error: {e}", "rows_inserted": 0}
```

Notes and tips:
- If you only want a simple route and don't need primary keys or conflict-upsert behavior, omit primary_key and let pandas.to_sql handle types and schema. (It will create the table automatically.)
- If you need an "upsert" behavior on conflicts, pass primary_key and conflict='replace' (or 'ignore').
- You can choose a table by CSS selector (selector param) or by table index (table_index). If selector finds multiple tables it will select the one at table_index within the matches.
- The function returns the parsed pandas.DataFrame inside the result for further inspection.

Here is a single self-contained Python function that opens an image, extracts text using Tesseract OCR (via pytesseract + Pillow), converts the text to a target encoding, and — if OCR yields nothing useful — falls back to extracting text from image comments/metadata (EXIF, PNG tEXt, JPEG comment, XP* tags, etc.).

Install requirements:
- Pillow: pip install pillow
- pytesseract: pip install pytesseract
- Tesseract OCR engine must be installed on your system (e.g., apt install tesseract-ocr or download for Windows/Mac). If tesseract is not on PATH, set pytesseract.pytesseract.tesseract_cmd before calling the function.

Code:

```python
def ocr_extract_and_convert(image_path,
                            target_encoding='utf-8',
                            lang=None,
                            return_bytes=True,
                            tesseract_cmd=None,
                            encode_errors='replace'):
    """
    Open an image, extract text using OCR (pytesseract). If OCR yields empty/whitespace-only text,
    fall back to extracting text from image comments/metadata (EXIF UserComment, ImageDescription,
    PNG tEXt, JPEG comment, XP* tags, etc.).

    Parameters:
    - image_path (str): path to the image file.
    - target_encoding (str): encoding to convert the extracted text into (default 'utf-8').
    - lang (str or None): language code(s) for Tesseract (e.g. 'eng', 'eng+fra'). If None, default Tesseract language used.
    - return_bytes (bool): if True (default) returns bytes encoded in target_encoding.
                           if False returns a Python str (decoded using target_encoding).
    - tesseract_cmd (str or None): path to the tesseract executable (if None, uses default).
                                   If supplied, this sets pytesseract.pytesseract.tesseract_cmd.
    - encode_errors (str): error handler for encoding step (e.g., 'strict', 'ignore', 'replace').

    Returns:
    - tuple (text_out, source): text_out is bytes (if return_bytes True) or str (if False).
                                source is either 'ocr' or 'metadata' indicating which was used.
    - Raises RuntimeError if neither OCR nor metadata yields any text.

    Example:
    >>> btext, src = ocr_extract_and_convert('photo.jpg', target_encoding='utf-8')
    >>> print(src)
    'ocr'
    """
    # Imports inside function so this can be copy-pasted as a single block
    from PIL import Image, ExifTags
    import pytesseract
    import io

    # Optionally set tesseract executable path
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    def _clean_text(t):
        if t is None:
            return ''
        # Normalize different whitespace and strip BOM/NULLs
        t = t.replace('\x00', '').strip()
        return t

    def _extract_metadata_text(img):
        """Extract textual metadata from PIL Image object. Return joined string or ''."""
        parts = []

        # 1) PNG tEXt / info fields
        info = getattr(img, 'info', {}) or {}
        for k, v in info.items():
            if v is None:
                continue
            # v may be bytes or str or dict
            if isinstance(v, bytes):
                # try decode best-effort
                for enc in ('utf-8', 'utf-16', 'latin-1'):
                    try:
                        s = v.decode(enc)
                        break
                    except Exception:
                        s = None
                if s:
                    parts.append(f"{k}: {s.strip()}")
            elif isinstance(v, str):
                if v.strip():
                    parts.append(f"{k}: {v.strip()}")
            elif isinstance(v, dict):
                # sometimes info['text'] is a dict of text chunks
                for kk, vv in v.items():
                    if isinstance(vv, bytes):
                        try:
                            s = vv.decode('utf-8')
                        except Exception:
                            s = vv.decode('latin-1', errors='ignore')
                        if s.strip():
                            parts.append(f"{kk}: {s.strip()}")
                    elif isinstance(vv, str) and vv.strip():
                        parts.append(f"{kk}: {vv.strip()}")

        # 2) EXIF tags (JPEG/TIFF)
        try:
            exif = img.getexif()
        except Exception:
            exif = None

        if exif:
            # Map tag ids to names
            tag_map = {v: k for k, v in ExifTags.TAGS.items()}
            for tag_id, value in exif.items():
                tag_name = ExifTags.TAGS.get(tag_id, str(tag_id))
                if value is None:
                    continue
                # Focus on likely textual tags
                if tag_name in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle', 'XPSubject', 'XPAuthor', 'XPKeywords'):
                    s = None
                    # UserComment follows TIFF/EXIF spec: leading charset header
                    if tag_name == 'UserComment' and isinstance(value, (bytes, bytearray)):
                        b = bytes(value)
                        # If header indicates encoding
                        if b.startswith(b'ASCII\0\0\0'):
                            try:
                                s = b[8:].decode('ascii', errors='replace')
                            except Exception:
                                s = b[8:].decode('latin-1', errors='replace')
                        elif b.startswith(b'UNICODE\0'):
                            try:
                                s = b[8:].decode('utf-16', errors='replace')
                            except Exception:
                                s = b[8:].decode('utf-8', errors='replace')
                        elif b.startswith(b'UTF8\0\0\0'):
                            s = b[8:].decode('utf-8', errors='replace')
                        else:
                            # try common encodings
                            for enc in ('utf-8', 'utf-16', 'latin-1'):
                                try:
                                    s = b.decode(enc)
                                    break
                                except Exception:
                                    s = None
                    else:
                        # XP* tags are often stored as UTF-16LE little-endian null-padded bytes
                        if isinstance(value, (bytes, bytearray)):
                            b = bytes(value)
                            try:
                                s = b.decode('utf-16le').rstrip('\x00')
                            except Exception:
                                # fallback
                                try:
                                    s = b.decode('utf-8', errors='replace')
                                except Exception:
                                    s = b.decode('latin-1', errors='replace')
                        else:
                            # str or numeric
                            s = str(value)
                    if s:
                        s = s.strip('\x00').strip()
                        if s:
                            parts.append(f"{tag_name}: {s}")

                # Also include generic ImageDescription or other textual tags
                elif isinstance(value, str) and value.strip():
                    parts.append(f"{tag_name}: {value.strip()}")

        # 3) JPEG comment (some files have 'comment' in info)
        comment = info.get('comment')
        if comment:
            if isinstance(comment, bytes):
                try:
                    cs = comment.decode('utf-8')
                except Exception:
                    cs = comment.decode('latin-1', errors='replace')
                if cs.strip():
                    parts.append(f"comment: {cs.strip()}")
            elif isinstance(comment, str) and comment.strip():
                parts.append(f"comment: {comment.strip()}")

        # Join and return
        if parts:
            return '\n\n'.join(parts)
        return ''

    # Main logic
    img = None
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise RuntimeError(f"Could not open image {image_path}: {e}")

    # Attempt OCR
    ocr_text = ''
    try:
        # pytesseract.image_to_string normally accepts PIL Image
        ocr_kwargs = {}
        if lang:
            ocr_kwargs['lang'] = lang
        raw = pytesseract.image_to_string(img, **ocr_kwargs)
        ocr_text = _clean_text(raw)
    except pytesseract.pytesseract.TesseractNotFoundError:
        # Tesseract not found; we'll fallback to metadata
        ocr_text = ''
    except Exception:
        # Any other tesseract error: ignore and fallback
        ocr_text = ''

    # Consider OCR result valid if contains non-whitespace and not too short
    use_source = None
    final_text = ''
    if ocr_text and any(ch.isalnum() for ch in ocr_text):
        final_text = ocr_text
        use_source = 'ocr'
    else:
        # Try metadata fallback
        meta_text = _extract_metadata_text(img)
        meta_text = _clean_text(meta_text)
        if meta_text and any(ch.isalnum() for ch in meta_text):
            final_text = meta_text
            use_source = 'metadata'
        else:
            # Nothing found
            raise RuntimeError("No textual content found by OCR or in image metadata/comment fields.")

    # Convert to the desired encoding. Python str -> bytes in target_encoding.
    try:
        text_bytes = final_text.encode(target_encoding, errors=encode_errors)
    except Exception as e:
        # As a last resort, encode via utf-8 then transcode
        try:
            text_bytes = final_text.encode('utf-8', errors='replace').decode('utf-8').encode(target_encoding, errors=encode_errors)
        except Exception:
            raise RuntimeError(f"Could not encode text to {target_encoding}: {e}")

    if return_bytes:
        return text_bytes, use_source
    else:
        # decode back to str using the target encoding so caller knows the exact encoding used
        try:
            return text_bytes.decode(target_encoding, errors=encode_errors), use_source
        except Exception:
            # If decode back fails, just return the original final_text
            return final_text, use_source
```

Notes:
- By default, the function returns bytes encoded in target_encoding. Set return_bytes=False to get a Python str.
- The fallback collects multiple metadata fields and returns them joined if OCR fails.
- You can pass tesseract_cmd='/usr/bin/tesseract' (or Windows path) if Tesseract is not on PATH.
- Errors during encoding default to 'replace' (so invalid characters are replaced rather than raising). Change encode_errors to 'strict' if you want exceptions on encoding errors.

Here's a single self-contained Python function that opens an image file, attempts OCR on it (using Tesseract via pytesseract if available), normalizes/detects text encoding (using chardet), and — if OCR yields nothing useful — falls back to extracting image comments / EXIF comment fields. It uses Pillow for image handling.

Dependencies:
- Pillow (pip install Pillow)
- pytesseract (pip install pytesseract) and the Tesseract binary (OS package; e.g., apt install tesseract-ocr or brew install tesseract) — optional (if absent, the code falls back to image comments)
- chardet (pip install chardet)

Function:

```python
import shutil
from typing import Optional
from PIL import Image, ExifTags
import chardet

def extract_text_from_image(path: str, lang: str = 'eng', ocr_config: str = '--psm 3') -> Optional[str]:
    """
    Open an image file, try OCR to extract text, normalize the encoding to Unicode (UTF-8),
    and if OCR returns nothing useful, fall back to extracting image comments / EXIF user comments.

    Returns a Unicode string if any text is found, otherwise None.

    Dependencies:
      - Pillow (pip install Pillow)
      - pytesseract (pip install pytesseract) and the Tesseract binary (optional)
      - chardet (pip install chardet)

    Notes:
      - If pytesseract or the tesseract binary is unavailable, OCR step is skipped and the
        function goes straight to image comment fallback.
      - The function tries to repair common mis-decoding cases (e.g., bytes decoded with latin1)
        by using chardet's encoding detection.
    """
    # Helper: normalize detected bytes/strings to a cleaned unicode string
    def _normalize_text(raw):
        if raw is None:
            return None
        # If bytes, detect encoding and decode
        if isinstance(raw, (bytes, bytearray)):
            guessed = chardet.detect(bytes(raw))
            enc = guessed.get('encoding') or 'utf-8'
            try:
                return bytes(raw).decode(enc, errors='replace')
            except Exception:
                return bytes(raw).decode('utf-8', errors='replace')
        # If already str, check for typical mis-decoding: many replacement chars or many non-printable
        if isinstance(raw, str):
            text = raw
            if '\ufffd' in text:  # replacement char present -> maybe wrong decoding
                try:
                    # re-encode naive-latin1 to get original bytes then detect
                    candidate_bytes = text.encode('latin1', errors='replace')
                    guessed = chardet.detect(candidate_bytes)
                    enc = guessed.get('encoding') or 'utf-8'
                    return candidate_bytes.decode(enc, errors='replace')
                except Exception:
                    return text
            return text
        # Fallback: str() conversion
        try:
            return str(raw)
        except Exception:
            return None

    # Helper: check if text looks "useful"
    def _useful_text(s):
        if not s:
            return False
        s_stripped = s.strip()
        if not s_stripped:
            return False
        # Very short text might be useless
        if len(s_stripped) < 3:
            return False
        # Ratio of printable characters
        printable = sum(1 for c in s_stripped if c.isprintable())
        ratio = printable / max(1, len(s_stripped))
        if ratio < 0.5:
            return False
        # If most chars are punctuation/digits only, it's likely not useful textual content
        letters = sum(1 for c in s_stripped if c.isalpha())
        if letters / max(1, len(s_stripped)) < 0.1:
            return False
        return True

    # Helper: extract comments & EXIF textual fields from a Pillow.Image
    def _extract_image_comments(img):
        parts = []
        info = getattr(img, 'info', {}) or {}
        # Generic info dictionary (PNG tEXt, JPEG comment etc.)
        for k, v in info.items():
            # Skip very small or irrelevant keys, but capture common text-like keys
            if k.lower() in ('comment', 'comments', 'description', 'text', 'caption', 'title'):
                parts.append(v)
            else:
                # also append any string/bytes info values that look textual
                if isinstance(v, (str, bytes, bytearray)) and len(str(v).strip()) > 0:
                    parts.append(v)

        # EXIF textual tags
        try:
            exif = img.getexif()
            if exif:
                for tag_id, value in exif.items():
                    tag = ExifTags.TAGS.get(tag_id, tag_id)
                    if tag in ('UserComment', 'ImageDescription', 'XPTitle', 'XPComment', 'XPSubject'):
                        parts.append(value)
        except Exception:
            # Not all images have EXIF or Pillow versions differ; ignore failures
            pass

        # Flatten to a single string, preferring the first useful piece
        extracted = []
        for p in parts:
            normalized = _normalize_text(p)
            if normalized:
                extracted.append(normalized)
        if not extracted:
            return None
        # return the first useful chunk, or join all if none marked useful
        for chunk in extracted:
            if _useful_text(chunk):
                return chunk
        return "\n".join(extracted).strip() or None

    # Open image
    try:
        img = Image.open(path)
    except Exception as e:
        raise RuntimeError(f"Failed to open image {path!r}: {e}")

    # Try OCR if pytesseract and tesseract binary are available
    ocr_text = None
    try:
        import pytesseract
        # check tesseract binary presence
        if shutil.which('tesseract') is not None:
            try:
                ocr_text_raw = pytesseract.image_to_string(img, lang=lang, config=ocr_config)
                ocr_text = _normalize_text(ocr_text_raw)
            except Exception:
                ocr_text = None
        else:
            # pytesseract installed but tesseract not found; skip OCR
            ocr_text = None
    except Exception:
        # pytesseract not installed or import failed; skip OCR
        ocr_text = None

    if _useful_text(ocr_text):
        return ocr_text.strip()

    # Fallback: extract image comments / EXIF textual fields
    comments_text = _extract_image_comments(img)
    if _useful_text(comments_text):
        return comments_text.strip()

    # If OCR returned something borderline but not judged useful, return it (best-effort)
    if ocr_text:
        return ocr_text.strip()

    # Nothing found
    return None
```

Example usage:
- pip install Pillow pytesseract chardet
- Ensure system tesseract binary is installed (or skip OCR and rely on comments)
- Call:
  text = extract_text_from_image("scanned.jpg", lang='eng')
  if text:
      print("Extracted text:", text)
  else:
      print("No text found.")

Here's a single self-contained Python function that extracts all URLs from a text, obtains the domain for each URL (using tldextract if available, with a fallback), resolves domains to IP addresses, and queries ip-api.com for geolocation data for each IP. It uses the requests library for HTTP calls (with a urllib fallback if requests is not installed).

Usage example (after the function): call extract_urls_geolocate(text) and it returns a dictionary keyed by registered domain with URLs, hostnames, resolved IPs and geolocation responses.

Code:

```python
import re
import socket
import json
from urllib.parse import urlparse

# Try to import requests (preferred) and tldextract (recommended).
# Fall back to urllib.request and a simple domain fallback if necessary.
try:
    import requests
except Exception:
    requests = None
    import urllib.request

try:
    import tldextract
except Exception:
    tldextract = None


def extract_urls_geolocate(text, ip_api_base="http://ip-api.com/json/", timeout=5.0):
    """
    Extract URLs from `text`, determine domains, resolve IPs, and query ip-api.com for each IP.
    Returns a dict keyed by registered domain with structure:
      {
        "<registered_domain>": {
          "urls": [...],            # list of original URLs that map to this registered domain
          "hostnames": [...],       # distinct hostnames seen (may include subdomains)
          "ips": [...],             # resolved IP addresses (distinct)
          "geo": {                  # mapping ip -> ip-api response dict or error dict
              "<ip>": {...}
          }
        },
        ...
      }

    Parameters:
      text (str): input text containing zero or more URLs.
      ip_api_base (str): base URL of the IP API endpoint (default ip-api.com).
      timeout (float): request timeout in seconds for HTTP calls.

    Notes:
      - This uses tldextract if available to reliably obtain the registered domain; otherwise it uses a heuristic.
      - Uses requests if installed, otherwise urllib.
      - ip-api.com has rate limits; for many IPs you may need to pace requests.
    """
    # 1) Extract URLs with a reasonably permissive regex
    url_regex = re.compile(r'(?i)\b((?:https?://|http://|ftp://|www\.)[^\s<>()]+)')
    raw_matches = url_regex.findall(text or "")
    # Clean trailing punctuation that often attaches to URLs in text
    def clean_url(u):
        return u.rstrip('.,;:)\]}\''"!?')

    urls = [clean_url(u) for u in raw_matches]
    if not urls:
        return {}

    # 2) Normalize URLs (ensure scheme for parsing)
    parsed_entries = []
    for u in urls:
        norm = u
        if norm.startswith("www."):
            norm = "http://" + norm
        parsed = urlparse(norm)
        hostname = parsed.hostname or ""
        if hostname:
            hostname = hostname.strip().lower()
        parsed_entries.append((u, hostname))

    # 3) Derive registered domain from hostname using tldextract if available, else fallback
    def get_registered_domain(hostname):
        if not hostname:
            return ""
        if tldextract:
            ext = tldextract.extract(hostname)
            if ext.suffix:
                return ext.registered_domain or (ext.domain + "." + ext.suffix)
            else:
                return ext.domain
        # Fallback heuristic: take last two labels
        parts = hostname.split('.')
        if len(parts) >= 2:
            return '.'.join(parts[-2:])
        return hostname

    domain_map = {}  # registered_domain -> data accumulator
    for orig_url, hostname in parsed_entries:
        regdom = get_registered_domain(hostname)
        if not regdom:
            continue
        entry = domain_map.setdefault(regdom, {"urls": [], "hostnames": set(), "ips": set(), "geo": {}})
        entry["urls"].append(orig_url)
        if hostname:
            entry["hostnames"].add(hostname)

    # 4) Resolve hostnames to IPs (consider all hostnames for each registered domain)
    def resolve_hostname_to_ips(hostname):
        ips = set()
        try:
            # getaddrinfo returns tuples with sockaddr containing the IP address
            for res in socket.getaddrinfo(hostname, None):
                sockaddr = res[4]
                # IPv4: sockaddr is (ip, port) but port is None here; IPv6: (ip, ...)
                ip = sockaddr[0]
                ips.add(ip)
        except socket.gaierror:
            # could not resolve
            pass
        return ips

    for regdom, data in domain_map.items():
        for host in list(data["hostnames"]):
            ips = resolve_hostname_to_ips(host)
            for ip in ips:
                data["ips"].add(ip)

    # 5) Query IP API for each IP
    def query_ip_api(ip):
        url = ip_api_base.rstrip('/') + '/' + ip
        try:
            if requests:
                resp = requests.get(url, timeout=timeout)
                resp.raise_for_status()
                return resp.json()
            else:
                with urllib.request.urlopen(url, timeout=timeout) as rsp:
                    body = rsp.read()
                    return json.loads(body.decode('utf-8', errors='replace'))
        except Exception as e:
            return {"status": "error", "message": str(e), "query": ip}

    for regdom, data in domain_map.items():
        for ip in list(data["ips"]):
            geo = query_ip_api(ip)
            data["geo"][ip] = geo

    # 6) Convert sets to lists for output
    out = {}
    for regdom, data in domain_map.items():
        out[regdom] = {
            "urls": sorted(set(data["urls"])),
            "hostnames": sorted(data["hostnames"]),
            "ips": sorted(data["ips"]),
            "geo": data["geo"],
        }
    return out


# Example usage:
if __name__ == "__main__":
    sample = """
    Check these links: https://www.python.org/about/ and http://example.com/some/path,
    also visit sub.example.co.uk/page and a raw www.test-site.org resource.
    """
    result = extract_urls_geolocate(sample)
    import pprint
    pprint.pprint(result)
```

Notes and suggestions:
- Install tldextract and requests for best results: pip install requests tldextract
- ip-api.com is used here (http://ip-api.com/json/{query}). It enforces rate limits (free tier ~45 req/min). For many IPs, add batching or delays, or use a paid/authorized geo-IP provider.
- The fallback registered-domain heuristic may be incorrect for some multi-level TLDs (e.g., "example.co.uk"); tldextract handles those correctly.

```python
import re
import socket
import urllib.parse
from typing import Dict, List, Any
from concurrent.futures import ThreadPoolExecutor, as_completed

import requests

# Optional: if tldextract is available, use it to get the registered domain (e.g. example.co.uk).
try:
    import tldextract
    _HAS_TLDEX = True
except Exception:
    _HAS_TLDEX = False


def extract_urls_and_geolocate(text: str,
                               ip_api_base: str = "http://ip-api.com/json/",
                               api_timeout: float = 5.0,
                               max_workers: int = 10) -> Dict[str, Any]:
    """
    Extracts all URLs from `text`, extracts the domain/host for each URL,
    resolves domain to IP addresses, and queries the IP API for geolocation
    data for each IP.

    Uses ip-api.com (http://ip-api.com/json/{ip}) by default. Be mindful of
    their usage limits (free tier rate limits apply).

    Returns a dict containing:
      - "urls": list of entries for each URL found:
          { "url": str,
            "hostname": str or None,
            "registered_domain": str or None,
            "domain_error": str or None }
      - "domains": mapping domain -> { "ips": [ip, ...], "resolve_error": str or None,
                                     "geo": { ip: geo_json_or_error } }

    Parameters:
      text: input string to search for URLs.
      ip_api_base: base URL for the IP API (default ip-api.com).
      api_timeout: timeout seconds for HTTP requests to the IP API.
      max_workers: maximum concurrent workers for DNS + API requests.

    Dependencies:
      - requests
      - (optional) tldextract for registered domain extraction
    """

    # Simple URL-matching regex: matches http(s)/ftp and www... patterns.
    url_re = re.compile(r'((?:https?://|ftp://|www\.)[^\s"<>\]\)]+)', re.IGNORECASE)

    found = url_re.findall(text or "")
    # Deduplicate while preserving order
    seen_urls = []
    seen_set = set()
    for u in found:
        if u not in seen_set:
            seen_set.add(u)
            seen_urls.append(u)

    url_entries: List[Dict[str, Any]] = []
    domains_set = set()

    for raw_url in seen_urls:
        normalized = raw_url
        # If URL begins with 'www.', add scheme for parsing
        if normalized.startswith("www."):
            normalized = "http://" + normalized
        try:
            parsed = urllib.parse.urlparse(normalized)
            hostname = parsed.hostname  # None if parse fails
        except Exception:
            hostname = None

        registered_domain = None
        if hostname:
            if _HAS_TLDEX:
                try:
                    td = tldextract.extract(hostname)
                    rd = ".".join(part for part in (td.domain, td.suffix) if part)
                    registered_domain = rd if rd else hostname
                except Exception:
                    registered_domain = hostname
            else:
                # fallback: use the hostname as registered domain if tldextract not available
                registered_domain = hostname

            domains_set.add(hostname)

        entry = {
            "url": raw_url,
            "hostname": hostname,
            "registered_domain": registered_domain,
            "domain_error": None,
        }
        url_entries.append(entry)

    # Prepare domain data structure
    domains_info: Dict[str, Dict[str, Any]] = {
        domain: {"ips": [], "resolve_error": None, "geo": {}} for domain in domains_set
    }

    # Resolve domains to IPs (both IPv4/IPv6)
    def resolve_domain(domain: str):
        try:
            infos = socket.getaddrinfo(domain, None)
            ips = []
            for info in infos:
                sockaddr = info[4]
                if not sockaddr:
                    continue
                ip = sockaddr[0]
                if ip not in ips:
                    ips.append(ip)
            return domain, ips, None
        except Exception as e:
            return domain, [], str(e)

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        # Resolve domains concurrently
        futures = {executor.submit(resolve_domain, d): d for d in domains_set}
        for fut in as_completed(futures):
            domain = futures[fut]
            try:
                dom, ips, err = fut.result()
                if err:
                    domains_info[domain]["resolve_error"] = err
                else:
                    domains_info[domain]["ips"] = ips
            except Exception as e:
                domains_info[domain]["resolve_error"] = str(e)

    # Query IP API for each IP (concurrently)
    def query_ip_api(ip: str):
        url = ip_api_base.rstrip("/") + "/" + ip
        try:
            resp = requests.get(url, timeout=api_timeout)
            # Return raw json if possible, else text
            try:
                data = resp.json()
            except Exception:
                data = {"_raw_text": resp.text, "http_status": resp.status_code}
            return ip, data, None
        except Exception as e:
            return ip, None, str(e)

    # Build list of unique IPs
    unique_ips = set()
    for d in domains_info.values():
        for ip in d["ips"]:
            unique_ips.add(ip)

    ip_futures = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for ip in unique_ips:
            ip_futures[executor.submit(query_ip_api, ip)] = ip

        for fut in as_completed(ip_futures):
            ip = ip_futures[fut]
            try:
                ip_ret, data, err = fut.result()
                if err:
                    # store error object
                    for domain, dinfo in domains_info.items():
                        if ip in dinfo["ips"]:
                            dinfo["geo"][ip] = {"error": err}
                else:
                    for domain, dinfo in domains_info.items():
                        if ip in dinfo["ips"]:
                            dinfo["geo"][ip] = data
            except Exception as e:
                for domain, dinfo in domains_info.items():
                    if ip in dinfo["ips"]:
                        dinfo["geo"][ip] = {"error": str(e)}

    # Attach domain resolution errors back to URL entries if hostname had issues
    host_to_entry_idxs = {}
    for idx, entry in enumerate(url_entries):
        h = entry["hostname"]
        if h:
            host_to_entry_idxs.setdefault(h, []).append(idx)
        else:
            entry["domain_error"] = "Could not parse hostname from URL"

    for domain, dinfo in domains_info.items():
        if dinfo["resolve_error"] and domain in host_to_entry_idxs:
            for idx in host_to_entry_idxs[domain]:
                url_entries[idx]["domain_error"] = dinfo["resolve_error"]

    return {
        "urls": url_entries,
        "domains": domains_info,
    }


