if __name__ == "__main__":
    sample = """
    Check these out:
    https://www.example.com/path?query=1
    http://subdomain.example.co.uk:8080/hello
    www.google.com/search?q=test
    ftp://ftp.example.org/resource
    """
    result = extract_urls_and_geolocate(sample)
