- ip-api.com is used by default; you can change ip_api_base to another IP-geolocation service if you prefer (adjust the JSON handling accordingly).
- If you need more accurate "registered domain" extraction (e.g., example.co.uk rather than sub.example.co.uk), install tldextract (pip install tldextract). The function will use it automatically if available.

Here's a compact, self-contained Python function that extracts the first URL from a string and returns the page title (or a clear error). It uses requests for fetching and BeautifulSoup for parsing HTML.

Make sure you have the required packages installed:
pip install requests beautifulsoup4

Code:

```python
import re
from typing import Dict, Optional
from urllib.parse import urlparse

import requests
from bs4 import BeautifulSoup


def fetch_title_from_text(text: str, timeout: float = 10.0) -> Dict[str, Optional[str]]:
    """
    Extract the first URL from `text`, fetch the page, and return its <title>.
    Returns a dict:
      - On success: {'ok': True, 'url': '<resolved url>', 'title': '<page title>'}
      - On failure: {'ok': False, 'error': '<error message>'}

    Examples:
      fetch_title_from_text("Check this out: https://example.com/page")
    """
    if not text or not text.strip():
        return {'ok': False, 'error': 'Input text is empty.'}

    # 1) Find a URL-like token (supports http(s):// and www.)
    url_regex = re.compile(r'(?i)\b((?:https?://|www\.)[^\s<>")\'\]]+)')
    m = url_regex.search(text)
    if not m:
        return {'ok': False, 'error': 'No URL found in input text.'}

    raw_url = m.group(1)

    # 2) Trim common trailing punctuation that may be attached to URLs in text
    trailing_chars = '.,:;!?)]}\'"'
    while raw_url and raw_url[-1] in trailing_chars:
        raw_url = raw_url[:-1]
    while raw_url and raw_url[0] in '([{"\'':
        raw_url = raw_url[1:]

    # 3) Ensure scheme present
    if raw_url.lower().startswith('www.'):
        url = 'http://' + raw_url
    else:
        url = raw_url

    # 4) Basic validation
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https') or not parsed.netloc:
        return {'ok': False, 'error': f'Extracted string is not a valid HTTP/HTTPS URL: {raw_url}'}

    # 5) Fetch the page
    headers = {
        'User-Agent': 'fetch-title-bot/1.0 (+https://example.com)'
    }
    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.RequestException as e:
        return {'ok': False, 'error': f'Failed to fetch URL: {e}'}

    # 6) Check HTTP status
    if not (200 <= resp.status_code < 300):
        return {'ok': False, 'error': f'URL returned non-success status code: {resp.status_code}'}

    # 7) Check content type (allow HTML-like types)
    content_type = resp.headers.get('Content-Type', '')
    if not any(t in content_type for t in ('text/html', 'application/xhtml+xml', 'text/html;')):
        # If content type is absent or doesn't look like HTML, still try but warn
        # We'll attempt parsing anyway but usually it's not an HTML page.
        pass

    # 8) Parse HTML and extract <title>
    try:
        soup = BeautifulSoup(resp.content, 'lxml')
    except Exception:
        # fallback to built-in parser
        soup = BeautifulSoup(resp.content, 'html.parser')

    title_tag = soup.find('title')
    if not title_tag or not title_tag.get_text(strip=True):
        return {'ok': False, 'error': 'Page has no <title> or it is empty.'}

    title = title_tag.get_text(separator=' ', strip=True)
    return {'ok': True, 'url': resp.url, 'title': title}
```

Usage example:
- fetch_title_from_text("Here's a link: https://www.python.org") returns
  {'ok': True, 'url': 'https://www.python.org/', 'title': 'Welcome to Python.org'}

The function is defensive (strips punctuation, adds scheme for www., handles redirects and errors) and returns structured results for easy programmatic use.

```python
import re
from typing import Dict
from urllib.parse import urlparse
import requests
from bs4 import BeautifulSoup

def extract_url_and_get_title(text: str, timeout: float = 10.0) -> Dict[str, str]:
    """
    Extract the first URL from `text` and return the page title.
    Returns a dict:
      - on success: {'status': 'ok', 'url': <full_url>, 'title': <page title>}
      - on failure: {'status': 'error', 'error': <message>}

    Notes:
      - Tries to recognize common URL forms (http(s)://..., www..., or bare domains).
      - If a scheme is missing, 'http://' is prepended before the request.
      - Requires 'requests' and 'beautifulsoup4' packages.

    Example:
      >>> extract_url_and_get_title("Check this out: https://example.com/page.")
      {'status': 'ok', 'url': 'https://example.com/page', 'title': 'Example Domain'}
    """
    if not text or not isinstance(text, str):
        return {"status": "error", "error": "Input must be a non-empty string."}

    # 1) Find candidate URLs. This is intentionally permissive; we'll validate below.
    # Matches http(s)://..., www...., or bare domain-like tokens containing a dot.
    url_pattern = re.compile(r'(https?://\S+|www\.\S+|\b\S+\.[a-zA-Z]{2,}\S*)', re.IGNORECASE)
    candidates = url_pattern.findall(text)
    if not candidates:
        return {"status": "error", "error": "No URL found in the provided text."}

    # characters that commonly trail a URL in text but aren't part of it
    trailing_chars = '.,;:!?)"\''

    def clean_candidate(c: str) -> str:
        # Strip surrounding angle brackets if present and trailing punctuation
        c = c.strip()
        if c.startswith('<') and c.endswith('>'):
            c = c[1:-1].strip()
        # strip trailing punctuation
        while c and c[-1] in trailing_chars:
            c = c[:-1]
        return c

    def ensure_scheme(u: str) -> str:
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*://', u):
            return 'http://' + u
        return u

    # 2) Validate candidates and pick the first that looks like a real URL
    url = None
    for cand in candidates:
        cand = clean_candidate(cand)
        if not cand:
            continue
        full = ensure_scheme(cand)
        parsed = urlparse(full)
        if parsed.scheme and parsed.netloc:
            url = full
            break
    if not url:
        return {"status": "error", "error": "No valid URL found in the provided text."}

    # 3) Fetch the page
    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; URLTitleFetcher/1.0; +https://example.com/)"
    }
    try:
        resp = requests.get(url, timeout=timeout, headers=headers, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {"status": "error", "error": f"Error fetching URL: {e}"}

    if resp.status_code < 200 or resp.status_code >= 400:
        return {"status": "error", "error": f"HTTP error {resp.status_code} retrieving the URL."}

    # 4) Ensure content-type is HTML (if available)
    content_type = resp.headers.get("Content-Type", "")
    if 'html' not in content_type.lower():
        # Not necessarily fatal; try to parse anyway, but warn if it's clearly not HTML
        # Return an error if it's a binary or unknown type
        if any(ct in content_type.lower() for ct in ('image/', 'application/octet-stream', 'application/pdf')):
            return {"status": "error", "error": f"Content-Type '{content_type}' does not appear to be HTML."}

    # 5) Parse the HTML and extract title (with fallback to og:title)
    try:
        soup = BeautifulSoup(resp.content, "html.parser")
    except Exception as e:
        return {"status": "error", "error": f"Failed to parse HTML: {e}"}

    title = None
    if soup.title and soup.title.string:
        title = soup.title.string.strip()
    if not title:
        # try meta og:title
        og = soup.find("meta", property="og:title")
        if og and og.get("content"):
            title = og["content"].strip()
    if not title:
        # try meta name="title"
        m = soup.find("meta", attrs={"name": "title"})
        if m and m.get("content"):
            title = m["content"].strip()

    if not title:
        return {"status": "error", "error": "No title element found on the page."}

    return {"status": "ok", "url": resp.url, "title": title}
```

This function is self-contained (requires the third-party packages requests and beautifulsoup4). It returns structured results and clear error messages for the common failure modes.

Here's a self-contained Python function that does what you asked. It uses the requests library to download the file, json to parse, and pathlib for safe path handling. It searches nested JSON structures for the specified key and locates the first string value that looks like an http(s) URL. The saved filename is "{sanitized_key}_{timestamp}.txt" with timestamp format "%Y%m%d%H%M%S%f".

If you don't have requests installed: pip install requests

```python
from typing import Optional, Union
import json
import re
from pathlib import Path
from datetime import datetime
from urllib.parse import urlparse
import requests

def download_file_from_json(json_str: str, key: str, save_dir: Optional[Union[str, Path]] = None) -> Path:
    """
    Parse a JSON string to find a URL associated with `key`, download the file, and save it with a timestamped filename.
    Filename format: '{sanitized_key}_{timestamp}.txt' where timestamp is '%Y%m%d%H%M%S%f'.
    The file is saved in `save_dir` or the current working directory if not provided.

    Returns:
        Path to the saved file.

    Raises:
        ValueError: for JSON errors, missing key/URL, or invalid URL.
        requests.RequestException: for network/download failures.
    """
    # Helper: check URL-like string
    def is_url(s: str) -> bool:
        try:
            p = urlparse(s)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    # Helper: recursively search for the key and attempt to return a URL string
    def find_url_for_key(obj, target_key):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target_key:
                    # If value is str and looks like URL, return it
                    if isinstance(v, str) and is_url(v):
                        return v
                    # If value is container, search inside it for any URL string
                    if isinstance(v, (dict, list)):
                        found = find_url_for_key(v, None)  # None means look for any URL string
                        if found:
                            return found
                # Continue searching deeper
                found = find_url_for_key(v, target_key)
                if found:
                    return found
        elif isinstance(obj, list):
            for item in obj:
                found = find_url_for_key(item, target_key)
                if found:
                    return found
        else:
            # If target_key is None, we are searching for any URL string in this leaf
            if target_key is None and isinstance(obj, str) and is_url(obj):
                return obj
        return None

    # Parse JSON
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    # Find the URL associated with the specified key
    url = find_url_for_key(data, key)
    if not url:
        raise ValueError(f"No URL found for key '{key}' in the provided JSON.")

    # Validate URL once more
    if not is_url(url):
        raise ValueError(f"Value found for key '{key}' is not a valid HTTP/HTTPS URL: {url}")

    # Prepare filename
    timestamp = datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    # sanitize key for filename
    safe_key = re.sub(r"[^A-Za-z0-9_.-]", "_", key) or "file"
    save_dir_path = Path(save_dir) if save_dir else Path.cwd()
    save_dir_path.mkdir(parents=True, exist_ok=True)
    out_path = save_dir_path / f"{safe_key}_{timestamp}.txt"

    # Download and save (streaming)
    try:
        with requests.get(url, stream=True, timeout=30) as resp:
            resp.raise_for_status()
            with open(out_path, "wb") as f:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        # If download failed, ensure no partial file remains
        try:
            if out_path.exists():
                out_path.unlink()
        except Exception:
            pass
        raise

    return out_path
```

Example usage:
- download_file_from_json(json_string, "download_url", "/tmp") -> returns Path to saved file.

```python
import os
import json
import requests
from io import BytesIO

def extract_phone_numbers(source, output_file, default_region='US'):
    """
    Extract phone numbers from a URL or a local file and save them as JSON.

    Requirements (install via pip if needed):
      - requests
      - beautifulsoup4
      - phonenumbers
      - PyPDF2 (optional, for PDF support)

    Parameters:
      - source (str): URL (http(s)://...) or local file path.
      - output_file (str): Path to write JSON output.
      - default_region (str): Default region (ISO 3166-1 alpha-2) for parsing ambiguous numbers (default 'US').

    Returns:
      - list of dicts representing extracted phone numbers (also saved to output_file).

    Each dict contains:
      - e164: international E.164 form if available (e.g. "+14155552671") or None
      - national: national formatting string (if available)
      - country_code: numeric country code (if available)
      - raw: raw matched substring
      - start: start index in the extracted text
      - end: end index in the extracted text

    Example:
      extract_phone_numbers("https://example.com", "phones.json", default_region="US")
    """
    # Lazy imports that may not always be available
    try:
        from bs4 import BeautifulSoup
    except ImportError as e:
        raise ImportError("beautifulsoup4 is required: pip install beautifulsoup4") from e

    try:
        import phonenumbers
        from phonenumbers import PhoneNumberFormat
    except ImportError as e:
        raise ImportError("phonenumbers is required: pip install phonenumbers") from e

    # Try to import PDF reader library
    PdfReader = None
    try:
        # PyPDF2 >= 2.0 uses PdfReader
        from PyPDF2 import PdfReader
    except Exception:
        try:
            # Older name
            from PyPDF2 import PdfFileReader as PdfReader
        except Exception:
            PdfReader = None

    def _text_from_html_bytes(content_bytes, encoding_hint=None):
        enc = encoding_hint or 'utf-8'
        try:
            text = content_bytes.decode(enc, errors='replace')
        except Exception:
            # fallback
            text = content_bytes.decode('utf-8', errors='replace')
        soup = BeautifulSoup(text, 'html.parser')
        # remove scripts/styles
        for s in soup(['script', 'style', 'noscript']):
            s.decompose()
        return soup.get_text(separator=' ')

    def _text_from_pdf_bytes(content_bytes):
        if PdfReader is None:
            raise RuntimeError("PDF support requires PyPDF2. Install with: pip install PyPDF2")
        reader = PdfReader(BytesIO(content_bytes))
        text_parts = []
        # PyPDF2 API: reader.pages (list-like)
        for page in getattr(reader, "pages", []):
            try:
                t = page.extract_text()
            except Exception:
                t = ''
            if t:
                text_parts.append(t)
        return "\n".join(text_parts)

    def _text_from_local_file(path):
        ext = os.path.splitext(path)[1].lower()
        if ext == '.pdf':
            if PdfReader is None:
                raise RuntimeError("PDF support requires PyPDF2. Install with: pip install PyPDF2")
            with open(path, 'rb') as f:
                content_bytes = f.read()
            return _text_from_pdf_bytes(content_bytes)
        else:
            # treat as HTML or plain text
            with open(path, 'rb') as f:
                content_bytes = f.read()
            # if looks like HTML
            if content_bytes.strip().lower().startswith(b'<!doctype') or b'<html' in content_bytes.lower():
                return _text_from_html_bytes(content_bytes)
            else:
                # decode heuristically
                try:
                    return content_bytes.decode('utf-8', errors='replace')
                except Exception:
                    return content_bytes.decode('latin-1', errors='replace')

    # Step 1: obtain textual content
    is_url = isinstance(source, str) and source.startswith(('http://', 'https://'))
    text = ''
    if is_url:
        resp = requests.get(source, timeout=20)
        resp.raise_for_status()
        content_type = resp.headers.get('content-type', '').lower()
        content = resp.content
        if 'pdf' in content_type or source.lower().endswith('.pdf'):
            text = _text_from_pdf_bytes(content)
        elif 'html' in content_type or b'<html' in content[:2048].lower():
            # try to get proper encoding from response
            encoding = resp.encoding or 'utf-8'
            text = _text_from_html_bytes(content, encoding_hint=encoding)
        else:
            # treat as plain text
            try:
                text = content.decode(resp.encoding or 'utf-8', errors='replace')
            except Exception:
                text = content.decode('utf-8', errors='replace')
    else:
        # local file
        if not os.path.exists(source):
            raise FileNotFoundError(f"Local file not found: {source}")
        text = _text_from_local_file(source)

    # Step 2: find phone numbers using phonenumbers library
    results = []
    seen = set()
    for match in phonenumbers.PhoneNumberMatcher(text, default_region):
        num = match.number
        try:
            e164 = phonenumbers.format_number(num, PhoneNumberFormat.E164)
        except Exception:
            e164 = None
        try:
            national = phonenumbers.format_number(num, PhoneNumberFormat.NATIONAL)
        except Exception:
            national = None
        country_code = getattr(num, "country_code", None)
        raw = getattr(match, "raw_string", None)
        start = getattr(match, "start", None)
        end = getattr(match, "end", None)

        # use e164 if available, otherwise raw as unique key
        unique_key = e164 or (raw.strip() if raw else None)
        if unique_key in seen:
            continue
        seen.add(unique_key)

        results.append({
            "e164": e164,
            "national": national,
            "country_code": country_code,
            "raw": raw,
            "start": start,
            "end": end
        })

    # Step 3: save to JSON
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2, ensure_ascii=False)

    return results
```

Notes:
- This uses the phonenumbers library (Google's lib) for robust parsing and formatting.
- For HTML it uses BeautifulSoup to extract visible text; for PDFs it tries to use PyPDF2 if available.
- If PyPDF2 is not installed and you need PDF support, install it: pip install PyPDF2.
- Example install command for all dependencies:
    pip install requests beautifulsoup4 phonenumbers PyPDF2
